1	/**
2	 * The durable store: what stands in for Postgres in this demo.
3	 *
4	 * The design assumes Postgres. The exercise says the program must run on
5	 * Node alone, so one JSON document on disk plays that part. Every
6	 * substitution is listed here, because a reviewer checking the code against
7	 * the design needs to know exactly which guarantees are real and which are
8	 * imitated:
9	 *
10	 * | Design (Postgres)            | Here                                            | Faithful? |
11	 * | ---------------------------- | ----------------------------------------------- | --------- |
12	 * | tables                       | keyed objects and arrays in one JSON document    | yes       |
13	 * | `BEGIN` / `COMMIT`           | {@link DurableStore.transaction} — mutate a deep | yes, for  |
14	 * |                              | clone, then write the file atomically; a throw   | one       |
15	 * |                              | discards the clone, so nothing is half-applied   | process   |
16	 * | durability across a restart  | `writeFileSync` to a temp path then `renameSync`,| yes — the |
17	 * |                              | which is atomic on POSIX                         | demo kills|
18	 * |                              |                                                  | a process |
19	 * | `SELECT ... FOR UPDATE`      | not needed: one process, one transaction at a    | imitated  |
20	 * |   (the per-record lock)      | time, so merges on a record cannot interleave    |           |
21	 * | `FOR UPDATE SKIP LOCKED`     | the `leaseOwner` / `leaseUntilMs` columns, which | yes — the |
22	 * |                              | the design uses anyway so a crashed sender's     | lease is  |
23	 * |                              | rows can be reclaimed                            | real      |
24	 * | partial unique index,        | an explicit check in {@link Tx.enqueueOutbound}  | imitated  |
25	 * |   one pending row per field  |                                                  |           |
26	 * | `LISTEN` / `NOTIFY`          | the demo calls the worker directly               | imitated  |
27	 * | monthly partitions, pruning  | not implemented; retention is a design concern   | absent    |
28	 *
29	 * What is *not* imitated is called out so nobody reads more into the demo than
30	 * it shows: there is no concurrency here, so this file cannot demonstrate that
31	 * the record-level lock serialises competing merges. It demonstrates the
32	 * rules, the ordering, and the durability.
33	 *
34	 * Errors are always surfaced. A read failure raises {@link StoreReadError} and
35	 * a write failure {@link StoreWriteError}, both carrying the underlying cause.
36	 * Nothing here catches an error in order to continue quietly: a swallowed
37	 * write failure would make a lost call look like a drained queue.
38	 */
39	
40	import { createHash } from "node:crypto";
41	import { existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
42	import { dirname, join } from "node:path";
43	
44	import { StoreReadError, StoreWriteError } from "../domain/types.js";
45	import type {
46	  EchoFenceRow,
47	  FieldChangeRow,
48	  FieldVersionRow,
49	  InboundEventRow,
50	  ObservationRow,
51	  OutboundRow,
52	  RecordLinkRow,
53	  RecordRow,
54	  StoreState,
55	} from "./schema.js";
56	import { emptyState, fieldKey, recordKey } from "./schema.js";
57	import type { ObjectType, OutboundReason, Origin } from "../domain/types.js";
58	
59	/** sha256, hex. Used for payload hashes and echo-fence value hashes. */
60	export function sha256(value: string): string {
61	  return createHash("sha256").update(value, "utf8").digest("hex");
62	}
63	
64	/**
65	 * The handle a transaction body uses. Every mutation goes through a named
66	 * method rather than raw object access, so the set of writes the design allows
67	 * is visible in one place.
68	 */
69	export class Tx {
70	  constructor(
71	    /** The deep clone being mutated. Discarded if the body throws. */
72	    readonly state: StoreState,
73	    private readonly nowMs: () => number,
74	  ) {}
75	
76	  // ---------------------------------------------------------------- records
77	
78	  /** The current values row, or undefined. */
79	  getRecord(objectType: ObjectType, portalId: string): RecordRow | undefined {
80	    return this.state.records[recordKey(objectType, portalId)];
81	  }
82	
83	  /** Create an empty record and its link. Used by part 5 cases (b) and the portal's create path. */
84	  createRecord(objectType: ObjectType, portalId: string, sfId: string | null): RecordRow {
85	    const row: RecordRow = {
86	      objectType,
87	      portalId,
88	      values: {},
89	      updatedAtMs: this.nowMs(),
90	    };
91	    this.state.records[recordKey(objectType, portalId)] = row;
92	    this.state.recordLinks.push({
93	      objectType,
94	      portalId,
95	      sfId,
96	      linkedAtMs: sfId === null ? undefined : this.nowMs(),
97	    });
98	    return row;
99	  }
100	
101	  /** Set a field's current value. The single place a current value changes. */
102	  setCurrentValue(
103	    objectType: ObjectType,
104	    portalId: string,
105	    field: string,
106	    value: string | null,
107	  ): void {
108	    const row = this.getRecord(objectType, portalId);
109	    if (!row) {
110	      // Not a recoverable condition: the caller resolved the record before
111	      // calling, so this means a bug in the caller, not bad input.
112	      throw new StoreReadError(
113	        `no ${objectType} record ${portalId} to set ${field} on`,
114	      );
115	    }
116	    row.values[field] = value;
117	    row.updatedAtMs = this.nowMs();
118	  }
119	
120	  // --------------------------------------------------------- field versions
121	
122	  getFieldVersion(
123	    objectType: ObjectType,
124	    portalId: string,
125	    field: string,
126	  ): FieldVersionRow | undefined {
127	    return this.state.fieldVersions[fieldKey(objectType, portalId, field)];
128	  }
129	
130	  /** Insert or replace the winning order key for a field. */
131	  putFieldVersion(row: FieldVersionRow): void {
132	    this.state.fieldVersions[fieldKey(row.objectType, row.portalId, row.field)] = row;
133	  }
134	
135	  // -------------------------------------------------------- history and log
136	
137	  /** Append a permanent history row. Never updated, never deleted. */
138	  appendFieldChange(row: Omit<FieldChangeRow, "seq" | "appliedAtMs">): FieldChangeRow {
139	    const full: FieldChangeRow = {
140	      ...row,
141	      seq: this.state.nextSeq++,
142	      appliedAtMs: this.nowMs(),
143	    };
144	    this.state.fieldChanges.push(full);
145	    return full;
146	  }
147	
148	  /** Append an operational observation: an echo, a confirmation, a restatement. */
149	  appendObservation(row: Omit<ObservationRow, "seq" | "observedAtMs">): void {
150	    this.state.observations.push({
151	      ...row,
152	      seq: this.state.nextSeq++,
153	      observedAtMs: this.nowMs(),
154	    });
155	  }
156	
157	  /** Permanent history for one record, oldest first. */
158	  historyFor(objectType: ObjectType, portalId: string): readonly FieldChangeRow[] {
159	    return this.state.fieldChanges.filter(
160	      (c) => c.objectType === objectType && c.portalId === portalId,
161	    );
162	  }
163	
164	  // ------------------------------------------------------- inbound dedupe
165	
166	  /**
167	   * Claim an event id, in the same transaction as the apply (design 8.1).
168	   *
169	   * Returns `"claimed"` on the first sight of this event and `"duplicate"`
170	   * when we have seen it. `"conflict"` means the same id arrived with a
171	   * different payload, which is a provider bug worth alerting on, because the
172	   * key we are trusting is not unique.
173	   */
174	  claimEvent(
175	    row: Omit<InboundEventRow, "receivedAtMs" | "outcome">,
176	  ): "claimed" | "duplicate" | "conflict" {
177	    const existing = this.state.inboundEvents[row.eventId];
178	    if (existing) {
179	      return existing.payloadHash === row.payloadHash ? "duplicate" : "conflict";
180	    }
181	    this.state.inboundEvents[row.eventId] = {
182	      ...row,
183	      outcome: "rejected",
184	      receivedAtMs: this.nowMs(),
185	    };
186	    return "claimed";
187	  }
188	
189	  /** Record how a claimed event turned out. */
190	  setEventOutcome(eventId: string, outcome: InboundEventRow["outcome"]): void {
191	    const row = this.state.inboundEvents[eventId];
192	    if (!row) {
193	      throw new StoreReadError(`event ${eventId} was never claimed`);
194	    }
195	    row.outcome = outcome;
196	  }
197	
198	  // -------------------------------------------------------- outbound queue
199	
200	  /**
201	   * Enqueue one outbound call.
202	   *
203	   * Stands in for the design's partial unique index on
204	   * `(object_type, portal_id, field) WHERE state = 'pending'`: at most one
205	   * pending row per field, so an echo arriving beside an already-queued repair
206	   * cannot pile up a second one (design 4, Appendix B step 5). Returns false
207	   * when a pending row already existed.
208	   */
209	  enqueueOutbound(args: {
210	    objectType: ObjectType;
211	    portalId: string;
212	    field: string;
213	    reason: OutboundReason;
214	    occurredAtMs: number;
215	  }): boolean {
216	    const already = this.state.outbound.some(
217	      (r) =>
218	        r.state === "pending" &&
219	        r.objectType === args.objectType &&
220	        r.portalId === args.portalId &&
221	        r.field === args.field,
222	    );
223	    if (already) return false;
224	    this.state.outbound.push({
225	      id: this.state.nextOutboundId++,
226	      objectType: args.objectType,
227	      portalId: args.portalId,
228	      field: args.field,
229	      reason: args.reason,
230	      occurredAtMs: args.occurredAtMs,
231	      state: "pending",
232	      attempts: 0,
233	      nextAttemptAtMs: this.nowMs(),
234	      createdAtMs: this.nowMs(),
235	    });
236	    return true;
237	  }
238	
239	  /** Every outbound row, for the worker and for the demo's printed output. */
240	  outboundRows(): readonly OutboundRow[] {
241	    return this.state.outbound;
242	  }
243	
244	  // ----------------------------------------------------------- echo fences
245	
246	  /** Record that we just wrote this exact canonical value (design 9.3). */
247	  addEchoFence(row: EchoFenceRow): void {
248	    this.state.echoFences.push(row);
249	  }
250	
251	  /**
252	   * Find and consume an unexpired fence for this field and value. Consuming it
253	   * is what stops one fence from masking a genuine later Salesforce change.
254	   */
255	  consumeEchoFence(
256	    objectType: ObjectType,
257	    portalId: string,
258	    field: string,
259	    valueHash: string,
260	  ): boolean {
261	    const now = this.nowMs();
262	    const i = this.state.echoFences.findIndex(
263	      (f) =>
264	        f.objectType === objectType &&
265	        f.portalId === portalId &&
266	        f.field === field &&
267	        f.valueHash === valueHash &&
268	        f.expiresAtMs > now,
269	    );
270	    if (i < 0) return false;
271	    this.state.echoFences.splice(i, 1);
272	    return true;
273	  }
274	
275	  // ------------------------------------------------------- links, watermark
276	
277	  findLinkBySfId(objectType: ObjectType, sfId: string): RecordLinkRow | undefined {
278	    return this.state.recordLinks.find(
279	      (l) => l.objectType === objectType && l.sfId === sfId,
280	    );
281	  }
282	
283	  findLinkByPortalId(objectType: ObjectType, portalId: string): RecordLinkRow | undefined {
284	    return this.state.recordLinks.find(
285	      (l) => l.objectType === objectType && l.portalId === portalId,
286	    );
287	  }
288	
289	  /** Record the Salesforce id a create returned. */
290	  linkSfId(objectType: ObjectType, portalId: string, sfId: string): void {
291	    const link = this.findLinkByPortalId(objectType, portalId);
292	    if (!link) {
293	      throw new StoreReadError(`no link for ${objectType} ${portalId}`);
294	    }
295	    link.sfId = sfId;
296	    link.linkedAtMs = this.nowMs();
297	  }
298	
299	  /** How many repairs this field has had in the last hour — rule L4 (design 9.4). */
300	  repairsInLastHour(objectType: ObjectType, portalId: string, field: string): number {
301	    const since = this.nowMs() - 60 * 60 * 1000;
302	    return this.state.outbound.filter(
303	      (r) =>
304	        r.reason === "repair" &&
305	        r.objectType === objectType &&
306	        r.portalId === portalId &&
307	        r.field === field &&
308	        r.createdAtMs >= since,
309	    ).length;
310	  }
311	}
312	
313	/**
314	 * A file-backed store with transactions.
315	 *
316	 * Construct one per process. The demo constructs a fresh one in each child
317	 * process it spawns, which is exactly how it proves that a queued call
318	 * survives a restart: the second process reads the same file.
319	 */
320	export class DurableStore {
321	  private state: StoreState;
322	
323	  private constructor(
324	    private readonly path: string,
325	    state: StoreState,
326	    private readonly nowMs: () => number,
327	  ) {
328	    this.state = state;
329	  }
330	
331	  /**
332	   * Open the store at `path`, creating an empty one if absent.
333	   *
334	   * @throws {StoreReadError} if the file exists but cannot be read or parsed.
335	   *   Deliberately fatal: continuing with an empty store would silently
336	   *   discard every queued call, which is the failure this whole design exists
337	   *   to prevent.
338	   */
339	  static open(path: string, nowMs: () => number = () => Date.now()): DurableStore {
340	    if (!existsSync(path)) {
341	      const store = new DurableStore(path, emptyState(), nowMs);
342	      store.persist();
343	      return store;
344	    }
345	    let raw: string;
346	    try {
347	      raw = readFileSync(path, "utf8");
348	    } catch (cause) {
349	      throw new StoreReadError(`cannot read store at ${path}`, cause);
350	    }
351	    try {
352	      return new DurableStore(path, JSON.parse(raw) as StoreState, nowMs);
353	    } catch (cause) {
354	      throw new StoreReadError(`store at ${path} is not valid JSON`, cause);
355	    }
356	  }
357	
358	  /**
359	   * Run `body` as one transaction.
360	   *
361	   * The body mutates a deep clone. On a clean return the clone is written to
362	   * disk atomically and becomes the live state; if the body throws, the clone
363	   * is dropped and the live state is untouched, so nothing is ever
364	   * half-applied. This is what lets the inbound path claim an event id and
365	   * apply the change together (design 5) — split across two commits, a crash
366	   * in between would mark an event processed that was never applied.
367	   *
368	   * The error is always re-thrown after the rollback. A transaction that
369	   * failed must never look like one that succeeded.
370	   */
371	  transaction<T>(body: (tx: Tx) => T): T {
372	    const draft = structuredClone(this.state);
373	    const tx = new Tx(draft, this.nowMs);
374	    let result: T;
375	    try {
376	      result = body(tx);
377	    } catch (error) {
378	      // Roll back by discarding the draft, then let the caller see the error.
379	      // Not swallowed: the caller decides whether this is a 400, a 500, or a
380	      // failed send.
381	      throw error;
382	    }
383	    const previous = this.state;
384	    this.state = draft;
385	    try {
386	      this.persist();
387	    } catch (error) {
388	      this.state = previous; // keep memory and disk in agreement
389	      throw error;
390	    }
391	    return result;
392	  }
393	
394	  /** Read-only view, for assertions and printed output. */
395	  read<T>(body: (tx: Tx) => T): T {
396	    return body(new Tx(this.state, this.nowMs));
397	  }
398	
399	  /**
400	   * Write the state atomically: temp file, then rename.
401	   *
402	   * @throws {StoreWriteError} on any failure, with the cause attached. A
403	   *   swallowed write failure here would be the worst bug in the program —
404	   *   the queue would look drained while the calls were never recorded.
405	   */
406	  private persist(): void {
407	    const tmp = `${this.path}.tmp`;
408	    try {
409	      mkdirSync(dirname(this.path), { recursive: true });
410	      writeFileSync(tmp, JSON.stringify(this.state, null, 2), "utf8");
411	      renameSync(tmp, this.path);
412	    } catch (cause) {
413	      try {
414	        if (existsSync(tmp)) unlinkSync(tmp);
415	      } catch (cleanupFailure) {
416	        // Cleanup is best-effort, but it is still reported rather than
417	        // discarded: a stray temp file is worth knowing about.
418	        process.emitWarning(
419	          `could not remove temp store file ${tmp}: ${String(cleanupFailure)}`,
420	        );
421	      }
422	      throw new StoreWriteError(`cannot write store at ${this.path}`, cause);
423	    }
424	  }
425	}
426	
427	/** Default on-disk location for the demo's state. */
428	export function defaultStatePath(dir = ".demo-state"): string {
429	  return join(dir, "store.json");
430	}
