1	/**
2	 * The sync worker: drains the durable queue to Salesforce under the rate
3	 * governor (design 6.2 to 6.5).
4	 *
5	 * Three things here are the reason a 6-hour outage and a process restart are
6	 * both survivable, and each is easy to get wrong:
7	 *
8	 * 1. **The sender reads each field's current value at send time**, never a
9	 *    value carried on the queue row. A city edit at 09:00 and another at
10	 *    11:00 during an outage then cost one call carrying the 11:00 value,
11	 *    instead of two calls with a window where Salesforce holds something we
12	 *    superseded two hours earlier (design 6.3).
13	 * 2. **A successful send updates `sfValue`.** Our own write is the most recent
14	 *    thing we know about Salesforce's state — more recent than a webhook
15	 *    describing an edit that happened before it. Appendix B traces the silent
16	 *    divergence that omitting this causes, and it is the bug that trace found.
17	 * 3. **An endpoint failure is not a row failure.** A refused connection says
18	 *    nothing about the row, so the row's attempt is given back and the circuit
19	 *    breaker counts it instead. Without that split, ten attempts at a
20	 *    five-minute backoff is under an hour, so every queued row would mark
21	 *    itself `failed` during the second hour of a six-hour outage — the backlog
22	 *    would destroy itself while waiting.
23	 */
24	
25	import { fieldNames } from "../domain/fields.js";
26	import type { ObjectType } from "../domain/types.js";
27	import {
28	  SalesforceRejected,
29	  SalesforceServerError,
30	  SalesforceThrottled,
31	  SalesforceUnreachable,
32	} from "../salesforce/client.js";
33	import type { SalesforceClient } from "../salesforce/client.js";
34	import { sha256 } from "../store/store.js";
35	import type { DurableStore, Tx } from "../store/store.js";
36	import type { OutboundRow } from "../store/schema.js";
37	import { ECHO_FENCE_TTL_MS } from "../inbound/endpoint.js";
38	import type { RateGovernor } from "./governor.js";
39	
40	/**
41	 * How long a claimed row is held before another sender may reclaim it.
42	 *
43	 * The design's value. Long enough that a slow call is not stolen from a live
44	 * sender, short enough that a crash costs at most this much delay on the rows
45	 * it was holding. The demo passes a much shorter one so the reclaim is visible
46	 * inside a few seconds, which is the same latitude the exercise grants for the
47	 * rate cap.
48	 */
49	export const LEASE_MS = 30_000;
50	
51	/** Consecutive endpoint failures before the breaker opens (design 6.4). */
52	export const BREAKER_THRESHOLD = 5;
53	
54	/** What one `runOnce` did, for the demo's printed output and for assertions. */
55	export interface DrainReport {
56	  readonly claimed: number;
57	  readonly sent: number;
58	  readonly skipped: number;
59	  readonly throttled: number;
60	  readonly endpointFailures: number;
61	  readonly rowFailures: number;
62	  readonly breakerOpen: boolean;
63	  readonly callsMade: number;
64	}
65	
66	/** One record's worth of work, after coalescing. */
67	interface RecordBatch {
68	  readonly objectType: ObjectType;
69	  readonly portalId: string;
70	  readonly rows: OutboundRow[];
71	}
72	
73	/**
74	 * The sender.
75	 *
76	 * One instance per process. In the design exactly one process sends at a time,
77	 * holding a Postgres advisory lock while others idle as standbys (ADR 0003),
78	 * because the 100 req/s cap is a single global budget and the cheapest correct
79	 * way to spend a global budget is from one place. The demo runs one process at
80	 * a time, so there is no lock here — {@link SyncWorker.reclaimExpiredLeases}
81	 * is the part of that design that *is* exercised, because it is what lets a
82	 * restarted process pick up what a killed one left behind.
83	 */
84	export class SyncWorker {
85	  private consecutiveEndpointFailures = 0;
86	  private breakerOpenUntilMs = 0;
87	
88	  constructor(
89	    private readonly store: DurableStore,
90	    private readonly salesforce: SalesforceClient,
91	    private readonly governor: RateGovernor,
92	    private readonly owner: string,
93	    private readonly nowMs: () => number = () => Date.now(),
94	    /** See {@link LEASE_MS}. Overridden by the demo so a reclaim is visible. */
95	    private readonly leaseMs: number = LEASE_MS,
96	  ) {}
97	
98	  /** True while the breaker is open and we are probing rather than draining. */
99	  get isBreakerOpen(): boolean {
100	    return this.nowMs() < this.breakerOpenUntilMs;
101	  }
102	
103	  /**
104	   * Return rows a dead sender left `inflight` once their lease has expired.
105	   *
106	   * This is step 1 of the design's loop and the whole reason the row carries a
107	   * lease rather than a plain claim flag: a restart must be a non-event, with
108	   * no manual intervention and no reconciliation script.
109	   */
110	  reclaimExpiredLeases(): number {
111	    return this.store.transaction((tx) => {
112	      let reclaimed = 0;
113	      const now = this.nowMs();
114	      for (const row of tx.outboundRows()) {
115	        if (row.state === "inflight" && (row.leaseUntilMs ?? 0) < now) {
116	          row.state = "pending";
117	          row.leaseOwner = undefined;
118	          row.leaseUntilMs = undefined;
119	          row.nextAttemptAtMs = now;
120	          // The attempt is NOT given back here: a row that crashed us mid-send
121	          // still counts, which is what stops one poison row from crashing us
122	          // in a loop forever (design 6.2).
123	          reclaimed += 1;
124	        }
125	      }
126	      return reclaimed;
127	    });
128	  }
129	
130	  /**
131	   * Claim one batch and send it.
132	   *
133	   * Returns a report rather than throwing, because every failure mode here is
134	   * expected and already has a rule: the caller's job is to print or assert on
135	   * the outcome, not to handle an exception.
136	   */
137	  async runOnce(maxRecords = 200): Promise<DrainReport> {
138	    this.reclaimExpiredLeases();
139	
140	    if (this.isBreakerOpen) {
141	      // Probe with a single request instead of claiming (design 6.4).
142	      return this.probe();
143	    }
144	
145	    const batches = this.claim(maxRecords);
146	    const claimed = batches.reduce((n, b) => n + b.rows.length, 0);
147	    let sent = 0;
148	    let skipped = 0;
149	    let throttled = 0;
150	    let endpointFailures = 0;
151	    let rowFailures = 0;
152	    const callsBefore = this.governor.grantedCount;
153	
154	    for (const batch of batches) {
155	      const outcome = await this.sendBatch(batch);
156	      switch (outcome) {
157	        case "sent":
158	          sent += batch.rows.length;
159	          break;
160	        case "skipped":
161	          skipped += batch.rows.length;
162	          break;
163	        case "throttled":
164	          throttled += batch.rows.length;
165	          break;
166	        case "endpoint-failure":
167	          endpointFailures += batch.rows.length;
168	          break;
169	        case "row-failure":
170	          rowFailures += batch.rows.length;
171	          break;
172	      }
173	    }
174	
175	    return {
176	      claimed,
177	      sent,
178	      skipped,
179	      throttled,
180	      endpointFailures,
181	      rowFailures,
182	      breakerOpen: this.isBreakerOpen,
183	      callsMade: this.governor.grantedCount - callsBefore,
184	    };
185	  }
186	
187	  /** Drain until nothing is due, or `maxPasses` is reached. */
188	  async drain(maxPasses = 100): Promise<DrainReport> {
189	    let total: DrainReport = {
190	      claimed: 0,
191	      sent: 0,
192	      skipped: 0,
193	      throttled: 0,
194	      endpointFailures: 0,
195	      rowFailures: 0,
196	      breakerOpen: false,
197	      callsMade: 0,
198	    };
199	    for (let pass = 0; pass < maxPasses; pass += 1) {
200	      const report = await this.runOnce();
201	      total = {
202	        claimed: total.claimed + report.claimed,
203	        sent: total.sent + report.sent,
204	        skipped: total.skipped + report.skipped,
205	        throttled: total.throttled + report.throttled,
206	        endpointFailures: total.endpointFailures + report.endpointFailures,
207	        rowFailures: total.rowFailures + report.rowFailures,
208	        breakerOpen: report.breakerOpen,
209	        callsMade: total.callsMade + report.callsMade,
210	      };
211	      if (report.claimed === 0 && !report.breakerOpen) break;
212	      if (report.breakerOpen) break;
213	    }
214	    return total;
215	  }
216	
217	  /** How many rows are still pending, for printed output. */
218	  pendingCount(): number {
219	    return this.store.read((tx) =>
220	      tx.outboundRows().filter((r) => r.state === "pending").length,
221	    );
222	  }
223	
224	  // -------------------------------------------------------------- internals
225	
226	  /**
227	   * Claim whole records, oldest-due first.
228	   *
229	   * Whole records, because all the fields owed on one record become one call
230	   * (design 6.3). Oldest-due first, because ordering by anything else can
231	   * starve a row that keeps losing to newer work.
232	   */
233	  private claim(maxRecords: number): RecordBatch[] {
234	    return this.store.transaction((tx) => {
235	      const now = this.nowMs();
236	      const due = tx
237	        .outboundRows()
238	        .filter((r) => r.state === "pending" && r.nextAttemptAtMs <= now);
239	
240	      const byRecord = new Map<string, OutboundRow[]>();
241	      for (const row of due) {
242	        const key = `${row.objectType}:${row.portalId}`;
243	        const list = byRecord.get(key);
244	        if (list) list.push(row);
245	        else byRecord.set(key, [row]);
246	      }
247	
248	      const ordered = [...byRecord.entries()]
249	        .sort((a, b) => {
250	          const aDue = Math.min(...a[1].map((r) => r.nextAttemptAtMs));
251	          const bDue = Math.min(...b[1].map((r) => r.nextAttemptAtMs));
252	          return aDue - bDue || a[0].localeCompare(b[0]);
253	        })
254	        .slice(0, maxRecords);
255	
256	      const batches: RecordBatch[] = [];
257	      for (const [, rows] of ordered) {
258	        const first = rows[0];
259	        if (!first) continue;
260	        for (const row of rows) {
261	          row.state = "inflight";
262	          row.leaseOwner = this.owner;
263	          row.leaseUntilMs = now + this.leaseMs;
264	          row.attempts += 1; // incremented on CLAIM, not on failure
265	        }
266	        batches.push({
267	          objectType: first.objectType,
268	          portalId: first.portalId,
269	          rows,
270	        });
271	      }
272	      return batches;
273	    });
274	  }
275	
276	  /**
277	   * Build and send one record's call, then settle every row in the batch.
278	   *
279	   * The values are read here, at send time, from the current-state table — not
280	   * from the queue rows, which carry no value at all.
281	   */
282	  private async sendBatch(
283	    batch: RecordBatch,
284	  ): Promise<"sent" | "skipped" | "throttled" | "endpoint-failure" | "row-failure"> {
285	    const plan = this.store.read((tx) => this.planCall(tx, batch));
286	
287	    if (plan.kind === "nothing-owed") {
288	      // Design 10.3's claim-time filter: the sweep (or an earlier send) has
289	      // already brought Salesforce into line, so condition (d) says nothing is
290	      // owed and the row would spend a request to change nothing.
291	      this.settle(batch, (row) => {
292	        row.state = "sent";
293	        row.sentAtMs = this.nowMs();
294	        row.lastError = "nothing owed: sf_value already equals the current value";
295	      });
296	      return "skipped";
297	    }
298	
299	    // One token per request, retries included, because the cap counts the
300	    // calls we make (design 6.4).
301	    await this.governor.acquire();
302	
303	    try {
304	      if (plan.sfId === null) {
305	        const { sfId } = await this.salesforce.upsertByExternalId(
306	          batch.objectType,
307	          batch.portalId,
308	          plan.values,
309	        );
310	        this.store.transaction((tx) => tx.linkSfId(batch.objectType, batch.portalId, sfId));
311	      } else {
312	        await this.salesforce.update(batch.objectType, plan.sfId, plan.values);
313	      }
314	    } catch (error) {
315	      return this.settleFailure(batch, error);
316	    }
317	
318	    // Success. The order of these three matters and they all happen AFTER the
319	    // response: a fence or an sfValue for a call that did not land would
320	    // suppress a real Salesforce change (design 6.3).
321	    this.consecutiveEndpointFailures = 0;
322	    this.governor.onSuccess();
323	    this.store.transaction((tx) => {
324	      const now = this.nowMs();
325	      for (const row of batch.rows) {
326	        const value = plan.values[row.field] ?? null;
327	        const fv = tx.getFieldVersion(batch.objectType, batch.portalId, row.field);
328	        if (fv) {
329	          // (2) in the module docstring: our own write is now the most recent
330	          // thing we know about Salesforce's state.
331	          fv.sfValue = value;
332	          fv.sfObservedAtMs = now;
333	        }
334	        tx.addEchoFence({
335	          objectType: batch.objectType,
336	          portalId: batch.portalId,
337	          field: row.field,
338	          valueHash: sha256(String(value)),
339	          sentAtMs: now,
340	          expiresAtMs: now + ECHO_FENCE_TTL_MS,
341	        });
342	      }
343	      for (const live of tx.outboundRows()) {
344	        if (batch.rows.some((r) => r.id === live.id)) {
345	          live.state = "sent";
346	          live.sentAtMs = now;
347	          live.leaseOwner = undefined;
348	          live.leaseUntilMs = undefined;
349	        }
350	      }
351	    });
352	    return "sent";
353	  }
354	
355	  /** Decide what to send for one record, or that nothing is owed. */
356	  private planCall(
357	    tx: Tx,
358	    batch: RecordBatch,
359	  ):
360	    | { kind: "call"; sfId: string | null; values: Record<string, string | null> }
361	    | { kind: "nothing-owed" } {
362	    const record = tx.getRecord(batch.objectType, batch.portalId);
363	    if (!record) {
364	      // The row references a record that does not exist. Not retryable, and
365	      // not silently ignorable either — it is a bug worth seeing.
366	      throw new Error(
367	        `outbound row for missing ${batch.objectType} ${batch.portalId}`,
368	      );
369	    }
370	    const values: Record<string, string | null> = {};
371	    let owed = false;
372	    for (const row of batch.rows) {
373	      const current = record.values[row.field] ?? null;
374	      const fv = tx.getFieldVersion(batch.objectType, batch.portalId, row.field);
375	      values[row.field] = current;
376	      if (fv?.sfValue === undefined || fv.sfValue !== current) owed = true;
377	    }
378	    if (!owed) return { kind: "nothing-owed" };
379	    const link = tx.findLinkByPortalId(batch.objectType, batch.portalId);
380	    // A record created in the portal has no Salesforce id yet, so it goes
381	    // through the external-id upsert, which is idempotent on OUR id (A5).
382	    const sfId = link?.sfId ?? null;
383	    if (sfId === null) {
384	      // A create must carry every field we hold, not only the owed ones.
385	      for (const field of fieldNames(batch.objectType)) {
386	        values[field] = record.values[field] ?? null;
387	      }
388	    }
389	    return { kind: "call", sfId, values };
390	  }
391	
392	  /**
393	   * Apply the design 6.5 settle table.
394	   *
395	   * The split between an endpoint failure and a row failure is the one thing
396	   * in this method that must not be simplified — see (3) in the module
397	   * docstring.
398	   */
399	  private settleFailure(
400	    batch: RecordBatch,
401	    error: unknown,
402	  ): "throttled" | "endpoint-failure" | "row-failure" {
403	    const now = this.nowMs();
404	
405	    if (error instanceof SalesforceThrottled) {
406	      // Slow down, and keep the work. Nothing is dropped: the row goes back to
407	      // pending with a later due time and its attempt restored, because being
408	      // throttled was not this row's fault.
409	      this.governor.onThrottled();
410	      const delay = error.retryAfterMs ?? this.backoffMs(batch);
411	      this.settle(batch, (row) => {
412	        row.state = "pending";
413	        row.attempts = Math.max(0, row.attempts - 1);
414	        row.nextAttemptAtMs = now + delay;
415	        row.leaseOwner = undefined;
416	        row.leaseUntilMs = undefined;
417	        row.lastError = `429: ${error.message}`;
418	      });
419	      return "throttled";
420	    }
421	
422	    if (error instanceof SalesforceUnreachable || error instanceof SalesforceServerError) {
423	      // An endpoint failure says nothing about the row.
424	      this.consecutiveEndpointFailures += 1;
425	      if (this.consecutiveEndpointFailures >= BREAKER_THRESHOLD) {
426	        this.breakerOpenUntilMs = now + 30_000;
427	      }
428	      this.settle(batch, (row) => {
429	        row.state = "pending";
430	        row.attempts = Math.max(0, row.attempts - 1); // the attempt is given back
431	        row.nextAttemptAtMs = now + this.backoffMs(batch);
432	        row.leaseOwner = undefined;
433	        row.leaseUntilMs = undefined;
434	        row.lastError = `endpoint: ${String(error)}`;
435	      });
436	      return "endpoint-failure";
437	    }
438	
439	    if (error instanceof SalesforceRejected) {
440	      // A row failure: a value the portal accepts and Salesforce refuses is a
441	      // schema disagreement a human must settle, so it is marked failed and
442	      // alerted rather than retried into the cap. The row is never deleted —
443	      // it keeps its lastError as the record that something needs a person.
444	      this.settle(batch, (row) => {
445	        row.state = "failed";
446	        row.leaseOwner = undefined;
447	        row.leaseUntilMs = undefined;
448	        row.lastError = `rejected: ${error.message}`;
449	      });
450	      process.emitWarning(
451	        `ALERT: Salesforce refused ${batch.objectType} ${batch.portalId}: ${error.message}`,
452	      );
453	      return "row-failure";
454	    }
455	
456	    // An error we did not anticipate. Treated as an endpoint failure, which is
457	    // the conservative choice because it keeps the work, and re-reported as a
458	    // warning so it cannot pass unnoticed. Never swallowed.
459	    this.consecutiveEndpointFailures += 1;
460	    this.settle(batch, (row) => {
461	      row.state = "pending";
462	      row.attempts = Math.max(0, row.attempts - 1);
463	      row.nextAttemptAtMs = now + this.backoffMs(batch);
464	      row.leaseOwner = undefined;
465	      row.leaseUntilMs = undefined;
466	      row.lastError = `unexpected: ${String(error)}`;
467	    });
468	    process.emitWarning(`unexpected send failure, work kept: ${String(error)}`);
469	    return "endpoint-failure";
470	  }
471	
472	  /** Exponential backoff with jitter, capped at five minutes (design 6.4). */
473	  private backoffMs(batch: RecordBatch): number {
474	    const attempts = Math.max(...batch.rows.map((r) => r.attempts), 1);
475	    const base = Math.min(2 ** attempts * 1000, 300_000);
476	    return Math.floor(base * (0.5 + Math.random() * 0.5));
477	  }
478	
479	  /** Mutate the live rows matching this batch, inside one transaction. */
480	  private settle(batch: RecordBatch, mutate: (row: OutboundRow) => void): void {
481	    this.store.transaction((tx) => {
482	      for (const live of tx.outboundRows()) {
483	        if (batch.rows.some((r) => r.id === live.id)) mutate(live);
484	      }
485	    });
486	  }
487	
488	  /** The breaker's single probe: one cheap call to see whether the link is back. */
489	  private async probe(): Promise<DrainReport> {
490	    const callsBefore = this.governor.grantedCount;
491	    await this.governor.acquire();
492	    try {
493	      await this.salesforce.queryChangedSince("Contact", Number.MAX_SAFE_INTEGER, 1);
494	      // Closed. Resume at half rate and ramp, which is what the outage
495	      // arithmetic in design 10.4 charges for.
496	      this.consecutiveEndpointFailures = 0;
497	      this.breakerOpenUntilMs = 0;
498	      this.governor.resumeAtHalfRate();
499	    } catch (error) {
500	      this.breakerOpenUntilMs = this.nowMs() + 30_000;
501	      process.emitWarning(`breaker still open: ${String(error)}`);
502	    }
503	    return {
504	      claimed: 0,
505	      sent: 0,
506	      skipped: 0,
507	      throttled: 0,
508	      endpointFailures: 0,
509	      rowFailures: 0,
510	      breakerOpen: this.isBreakerOpen,
511	      callsMade: this.governor.grantedCount - callsBefore,
512	    };
513	  }
514	}
515

