1	/**
2	 * The rate governor: a token bucket with additive-increase /
3	 * multiplicative-decrease, implementing design 6.4.
4	 *
5	 * The design runs at 70 of the 100 requests per second Salesforce allows. The
6	 * demo configures a deliberately low ceiling so the wait is visible, which the
7	 * exercise explicitly permits — but the code enforces whatever cap it is
8	 * given, which is the property being demonstrated.
9	 *
10	 * One token per HTTP request **including every retry**, because the exercise
11	 * is explicit that the cap counts retries.
12	 */
13	
14	/** A clock and a sleep, injected so tests do not have to wait in real time. */
15	export interface GovernorClock {
16	  nowMs(): number;
17	  sleep(ms: number): Promise<void>;
18	}
19	
20	/** The real clock. */
21	export const realClock: GovernorClock = {
22	  nowMs: () => Date.now(),
23	  sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
24	};
25	
26	export interface GovernorOptions {
27	  /** The ceiling, in requests per second. The design's value is 70. */
28	  readonly ceilingPerSecond: number;
29	  /** Floor for the multiplicative decrease, so we never stall completely. */
30	  readonly floorPerSecond?: number;
31	  /** Added back per recovery step. The design's value is 5. */
32	  readonly increasePerStep?: number;
33	  /** How long a clean run must last before a recovery step. Design: 30 s. */
34	  readonly recoveryStepMs?: number;
35	  readonly clock?: GovernorClock;
36	}
37	
38	/**
39	 * Token bucket with AIMD.
40	 *
41	 * Why additive recovery is slower than the halving (design 6.4): a
42	 * rate-limited period should not oscillate. Halving reacts immediately to a
43	 * signal we were given; recovery has to probe, because nothing tells us the
44	 * limit has lifted.
45	 */
46	export class RateGovernor {
47	  private ratePerSecond: number;
48	  private readonly ceiling: number;
49	  private readonly floor: number;
50	  private readonly increase: number;
51	  private readonly recoveryStepMs: number;
52	  private readonly clock: GovernorClock;
53	
54	  private tokens: number;
55	  private lastRefillMs: number;
56	  private lastDecreaseMs: number;
57	
58	  /** Requests granted, for the demo's printed output and for assertions. */
59	  private granted = 0;
60	
61	  constructor(options: GovernorOptions) {
62	    if (options.ceilingPerSecond <= 0) {
63	      throw new RangeError("ceilingPerSecond must be positive");
64	    }
65	    this.ceiling = options.ceilingPerSecond;
66	    this.floor = options.floorPerSecond ?? Math.min(1, options.ceilingPerSecond);
67	    this.increase = options.increasePerStep ?? 5;
68	    this.recoveryStepMs = options.recoveryStepMs ?? 30_000;
69	    this.clock = options.clock ?? realClock;
70	    this.ratePerSecond = this.ceiling;
71	    this.tokens = this.ceiling;
72	    this.lastRefillMs = this.clock.nowMs();
73	    this.lastDecreaseMs = 0;
74	  }
75	
76	  /** The rate currently allowed, in requests per second. */
77	  get currentRate(): number {
78	    return this.ratePerSecond;
79	  }
80	
81	  /** How many requests this governor has granted. */
82	  get grantedCount(): number {
83	    return this.granted;
84	  }
85	
86	  /**
87	   * Resume at half the ceiling, which is what the circuit breaker does on
88	   * close (design 6.4) and what the outage arithmetic in 10.4 charges for.
89	   */
90	  resumeAtHalfRate(): void {
91	    this.ratePerSecond = Math.max(this.floor, this.ceiling / 2);
92	    this.lastDecreaseMs = this.clock.nowMs();
