1	/**
2	 * The seam at Salesforce.
3	 *
4	 * This is the one interface in the design with two real adapters: the live
5	 * HTTPS client against the client's org, and the fake in `./fake.ts` that the
6	 * demo runs against. Everything else in the codebase depends on this shape
7	 * rather than on either adapter (design 2, "Seams").
8	 *
9	 * Three operations, which is the entire surface the design depends on, and
10	 * **each is idempotent by design** (Appendix C.1). That is a requirement, not
11	 * an observation: a durable queue can only promise at-least-once delivery, so
12	 * a call that may be repeated must converge rather than double-apply.
13	 *
14	 * The error types below are the design's failure taxonomy, and the split
15	 * between them is what makes a 6-hour outage survivable (design 6.4):
16	 *
17	 * - {@link SalesforceUnreachable} and {@link SalesforceServerError} are
18	 *   **endpoint failures** — they say nothing about the row, so the row's
19	 *   attempt count is given back and the circuit breaker counts them.
20	 * - {@link SalesforceThrottled} is a slow-down signal: halve the rate, keep
21	 *   the work.
22	 * - {@link SalesforceRejected} is a **row failure** — the data in this
23	 *   particular record is wrong, so only this kind counts attempts toward
24	 *   giving up, and it alerts rather than retrying forever.
25	 */
26	
27	import type { ObjectType } from "../domain/types.js";
28	
29	/** The Salesforce login every call of ours is made as (design 9.2, rule L2). */
30	export const INTEGRATION_USER = "integration.user@tequity.example";
31	
32	/** Salesforce could not be reached at all. An endpoint failure. */
33	export class SalesforceUnreachable extends Error {
34	  constructor(message = "salesforce is unreachable") {
35	    super(message);
36	    this.name = "SalesforceUnreachable";
37	  }
38	}
39	
40	/** Salesforce answered 5xx. An endpoint failure — nothing about the row. */
41	export class SalesforceServerError extends Error {
42	  constructor(readonly status: number, message = `salesforce returned ${status}`) {
43	    super(message);
44	    this.name = "SalesforceServerError";
45	  }
46	}
47	
48	/**
49	 * Salesforce told us to slow down (429 or `REQUEST_LIMIT_EXCEEDED`,
50	 * assumption A8). Carries `Retry-After` when Salesforce supplied one.
51	 */
52	export class SalesforceThrottled extends Error {
53	  constructor(readonly retryAfterMs: number | undefined, message = "slow down") {
54	    super(message);
55	    this.name = "SalesforceThrottled";
56	  }
57	}
58	
59	/**
60	 * Salesforce refused this record's data (a 400-class validation error). A row
61	 * failure: a value the portal accepts and Salesforce will not is a schema
62	 * disagreement that needs a human, so retrying it blindly only burns the cap.
63	 */
64	export class SalesforceRejected extends Error {
65	  constructor(message: string) {
66	    super(message);
67	    this.name = "SalesforceRejected";
68	  }
69	}
70	
71	/** One record as the changed-since query returns it (design A4). */
72	export interface ChangedRecord {
73	  readonly sfId: string;
74	  readonly objectType: ObjectType;
75	  /** Every field of the record — this query is inherently full-record. */
76	  readonly values: Readonly<Record<string, string | null>>;
77	  /**
78	   * The record's modification time, **not** the field's. This is why the
79	   * restatement rule has to be unconditional (design 10.3).
80	   */
81	  readonly systemModstampMs: number;
82	  readonly lastModifiedBy: string;
83	}
84	
85	/** The three operations, and nothing else. */
86	export interface SalesforceClient {
87	  /**
88	   * Update an existing record with its current values.
89	   *
90	   * Idempotent because it sends the values we currently believe are right, so
91	   * sending it twice reaches the same state.
92	   *
93	   * @throws {SalesforceUnreachable} {@link SalesforceServerError}
94	   *   {@link SalesforceThrottled} {@link SalesforceRejected}
95	   */
96	  update(
97	    objectType: ObjectType,
98	    sfId: string,
99	    values: Readonly<Record<string, string | null>>,
100	  ): Promise<void>;
101	
102	  /**
103	   * Create or update by **our** identifier (assumption A5).
104	   *
105	   * Idempotent because it is keyed on the `portalId` we chose, so a repeat
106	   * updates the record it created rather than making a second one. This is
107	   * the operation worth pushing the client for: without it, create is the one
108	   * call whose repeat is not safe.
109	   */
110	  upsertByExternalId(
111	    objectType: ObjectType,
112	    portalId: string,
113	    values: Readonly<Record<string, string | null>>,
114	  ): Promise<{ sfId: string; created: boolean }>;
115	
116	  /**
117	   * Records changed since a watermark, oldest first (assumption A4). A read,
118	   * so trivially idempotent. Returns up to `pageSize` records.
119	   */
120	  queryChangedSince(
121	    objectType: ObjectType,
122	    sinceMs: number,
123	    pageSize: number,
124	  ): Promise<readonly ChangedRecord[]>;
125	}
