1	/**
2	 * The webhook endpoint: one HTTP request becomes one database transaction
3	 * (design 5).
4	 *
5	 * Four properties of this module are deliberate and are the reason it looks
6	 * the way it does:
7	 *
8	 * 1. **The duplicate claim and the apply share one transaction.** Split them
9	 *    and a crash in between marks an event processed that was never applied —
10	 *    and Salesforce will never resend it, because assumption A7 only promises
11	 *    redelivery while we have not yet answered 200. This is the single most
12	 *    important line in the path.
13	 * 2. **No network call happens inside the transaction.** That keeps the
14	 *    endpoint fast and stops a Salesforce outage turning into held locks.
15	 * 3. **Fields are independent.** One event can apply `phone` while
16	 *    superseding `city`; the event's outcome is then `partial`.
17	 * 4. **The 200 is returned only after the commit.** We never answer
18	 *    "accepted, will process later", because that is a promise with no
19	 *    durable record of having been made.
20	 */
21	
22	import { randomUUID } from "node:crypto";
23	
24	import { applyChanges } from "../domain/merge.js";
25	import { canonicalise } from "../domain/canonical.js";
26	import { WebhookRejected } from "../domain/types.js";
27	import type { AppliedField, EventOutcome, ObjectType } from "../domain/types.js";
28	import { INTEGRATION_USER } from "../salesforce/client.js";
29	import { sha256 } from "../store/store.js";
30	import type { DurableStore, Tx } from "../store/store.js";
31	import { validateWebhook } from "./validate.js";
32	import type { ValidWebhook } from "./validate.js";
33	
34	/** What the endpoint answers. Mirrors the status table in Appendix C.1. */
35	export interface WebhookResponse {
36	  readonly status: 200 | 400 | 500 | 503;
37	  readonly body: {
38	    readonly status: EventOutcome | "error";
39	    readonly reason?: string;
40	    readonly fields?: readonly AppliedField[];
41	    readonly retryAfterSeconds?: number;
42	  };
43	}
44	
45	/** How long an unresolvable create echo may defer before we give up (design 5). */
46	const CREATE_ECHO_DEFER_LIMIT_MS = 60_000;
47	
48	/** How long an echo fence stays valid (design 9.3). */
49	export const ECHO_FENCE_TTL_MS = 15 * 60 * 1000;
50	
51	/**
52	 * Handle one webhook body.
53	 *
54	 * Signature verification is the caller's job (see `verifySignature`), because
55	 * it needs the raw bytes and the headers; this function owns everything from
56	 * validation inward.
57	 *
58	 * Never throws for bad input: every refusal comes back as a
59	 * {@link WebhookResponse} carrying the status and a specific reason, so the
60	 * caller — an HTTP server, or the demo — has one thing to print or return.
61	 * Unexpected failures become a 500, which asks Salesforce to retry, and that
62	 * retry is safe because of the event claim.
63	 */
64	export function receiveWebhook(
65	  store: DurableStore,
66	  rawBody: string,
67	  nowMs: () => number = () => Date.now(),
68	): WebhookResponse {
69	  let webhook: ValidWebhook;
70	  try {
71	    webhook = validateWebhook(rawBody);
72	  } catch (error) {
73	    if (error instanceof WebhookRejected) {
74	      return { status: error.status, body: { status: "error", reason: error.reason } };
75	    }
76	    // Not a validation problem, so not the sender's fault: ask for a retry
77	    // rather than discarding a real edit over our own bug.
78	    return {
79	      status: 500,
80	      body: { status: "error", reason: `unexpected-validation-failure: ${String(error)}` },
81	    };
82	  }
83	
84	  try {
85	    return store.transaction((tx) => applyWebhook(tx, webhook, nowMs));
86	  } catch (error) {
87	    if (error instanceof WebhookRejected) {
88	      return { status: error.status, body: { status: "error", reason: error.reason } };
89	    }
90	    // The transaction rolled back, so nothing was half-applied. A 500 is
91	    // correct and the retry is safe: the event claim was rolled back with
92	    // everything else, so the redelivery will be treated as new.
93	    return {
94	      status: 500,
95	      body: { status: "error", reason: `apply-failed: ${String(error)}` },
96	    };
97	  }
98	}
99	
100	/** The transaction body. Runs entirely inside `store.transaction`. */
101	function applyWebhook(
102	  tx: Tx,
103	  webhook: ValidWebhook,
104	  nowMs: () => number,
105	): WebhookResponse {
106	  // --- step 4 of design 5: claim the event, in this same transaction -------
107	  const claim = tx.claimEvent({
108	    eventId: webhook.eventId,
109	    objectType: webhook.objectType,
110	    sfId: webhook.recordId,
111	    occurredAtMs: webhook.occurredAtMs,
112	    payloadHash: sha256(JSON.stringify(webhook.changedFields)),
113	  });
114	  if (claim === "duplicate") {
115	    // Salesforce has done nothing wrong — A7 permits a second delivery — so
116	    // this is counted, not alerted, and nothing happens. Note that even if
117	    // this table were pruned, the strict `>` of design 7.2 would make the
118	    // re-apply a no-op anyway; suppression saves work, strictness is the
119	    // guarantee (design 8.1).
120	    return { status: 200, body: { status: "duplicate" } };
121	  }
122	  if (claim === "conflict") {
123	    // The same eventId with a different payload means the key we are trusting
124	    // is not unique. First write wins, and this one DOES deserve an alert.
125	    return {
126	      status: 200,
127	      body: { status: "duplicate", reason: "eventId-reused-with-different-payload" },
128	    };
129	  }
130	
131	  // --- step 5: resolve and lock the record --------------------------------
132	  const resolved = resolveRecord(tx, webhook, nowMs);
133	  if (resolved.kind === "defer") {
134	    return {
135	      status: 503,
136	      body: { status: "error", reason: resolved.reason, retryAfterSeconds: 5 },
137	    };
138	  }
139	  const portalId = resolved.portalId;
140	
141	  // --- step 6: classify the whole event as echo or not (design 9.2, 9.3) --
142	  const isEcho = classifyEcho(tx, webhook, portalId);
143	
144	  // --- step 7: the per-field rules live in the merge ----------------------
145	  const fields = applyChanges(tx, {
146	    objectType: webhook.objectType,
147	    portalId,
148	    origin: "salesforce",
149	    actor: webhook.changedBy,
150	    occurredAtMs: webhook.occurredAtMs,
151	    originEventId: webhook.eventId,
152	    rawChanges: webhook.changedFields,
153	    isEcho,
154	  });
155	
156	  // --- step 8: record how the event turned out ----------------------------
157	  const outcome = summarise(fields, isEcho);
158	  tx.setEventOutcome(webhook.eventId, outcome);
159	  return { status: 200, body: { status: outcome, fields } };
160	}
161	
162	type Resolved =
163	  | { kind: "resolved"; portalId: string }
164	  | { kind: "defer"; reason: string };
165	
166	/**
167	 * Design 5's three cases.
168	 *
169	 * Case (c) is the subtle one: the echo of a create *we* made can arrive before
170	 * we have recorded the Salesforce id that create returned. Treating it as a
171	 * new record would mint a second local record for one real contact, so instead
172	 * we answer 503 and ask Salesforce to tell us again in a moment, borrowing the
173	 * redelivery we already assume (A7) rather than adding a holding table or
174	 * making a Salesforce call inside the transaction.
175	 *
176	 * It is narrowed to the integration user on purpose. Deferring whenever *any*
177	 * create is in flight would delay legitimate Salesforce creates by five
178	 * seconds most of the time, spending the latency budget to fix a race that
179	 * only involves our own writes.
180	 */
181	function resolveRecord(tx: Tx, webhook: ValidWebhook, nowMs: () => number): Resolved {
182	  const link = tx.findLinkBySfId(webhook.objectType, webhook.recordId);
183	  if (link) return { kind: "resolved", portalId: link.portalId };
184	
185	  if (webhook.changedBy === INTEGRATION_USER) {
186	    // Is there a create of ours still waiting for its Salesforce id?
187	    const unlinked = tx.state.recordLinks.find(
188	      (l) => l.objectType === webhook.objectType && l.sfId === null,
189	    );
190	    if (unlinked) {
191	      const waitedMs = nowMs() - (unlinked.linkedAtMs ?? nowMs());
192	      if (waitedMs < CREATE_ECHO_DEFER_LIMIT_MS) {
193	        return { kind: "defer", reason: "create-echo-before-link" };
194	      }
195	      // Bounded: past the limit we stop deferring, log loudly, and fall
196	      // through to case (b), letting the unique index and a reconciliation
197	      // sweep catch the duplicate. A visible, repairable outcome beats a stall.
198	      process.emitWarning(
199	        `create echo for ${webhook.recordId} unresolvable after ${waitedMs}ms; treating as a Salesforce-side create`,
200	      );
201	    }
202	  }
203	
204	  // Case (b): a record created in Salesforce that we have not seen. Mint an
205	  // id, link it, and let the merge apply every field as a first write. Outage
206	  // recovery reuses exactly this path (design 10.3).
207	  const portalId = randomUUID();
208	  tx.createRecord(webhook.objectType, portalId, webhook.recordId);
209	  return { kind: "resolved", portalId };
210	}
211	
212	/**
213	 * Rules L2 and L3 of design 9.
214	 *
215	 * L2 (the actor check) is the primary rule and catches essentially every echo,
216	 * because every call we make is made as the one integration login. It is
217	 * load-bearing rather than tidy: the echo of our own write carries the time
218	 * Salesforce stored it, which is later than the edit that write overwrote, so
219	 * compared as a change it would win and launder our value back over a newer
220	 * edit from the other side (Appendix B).
221	 *
222	 * L3 (the fence) is the same guarantee keyed on the value rather than the
223	 * actor, so it still holds if assumption A6 is false.
224	 *
225	 * **One simplification against the design:** the design's fence is per field,
226	 * while `applyChanges` takes one classification for the event, so here an
227	 * event counts as an echo only if *every* changed field matches an unexpired
228	 * fence. That is strictly more conservative — it never classifies a real
229	 * change as an echo — and it preserves L3's guarantee for the single-field
230	 * writes the sender actually makes, since coalescing sends one record at a
231	 * time and the fence is written per field sent.
232	 */
233	function classifyEcho(tx: Tx, webhook: ValidWebhook, portalId: string): boolean {
234	  if (webhook.changedBy === INTEGRATION_USER) return true;
235	
236	  const fields = Object.keys(webhook.changedFields);
237	  let matched = 0;
238	  for (const field of fields) {
239	    const raw = webhook.changedFields[field] ?? null;
240	    // Canonical form, because the fence stores the hash of what we SENT, and
241	    // Salesforce may have reformatted it on the way back (design 7.3).
242	    const canonical = canonicalise(webhook.objectType, field, raw);
243	    if (
244	      tx.consumeEchoFence(
245	        webhook.objectType,
246	        portalId,
247	        field,
248	        sha256(String(canonical)),
249	      )
250	    ) {
251	      matched += 1;
252	    }
253	  }
254	  return matched > 0 && matched === fields.length;
255	}
256	
257	/** Collapse the per-field outcomes into the event's own outcome. */
258	function summarise(fields: readonly AppliedField[], isEcho: boolean): EventOutcome {
259	  if (isEcho) return "echo";
260	  const kinds = new Set(fields.map((f) => f.outcome));
261	  if (kinds.size === 1) {
262	    const only = [...kinds][0];
263	    if (only === "applied") return "applied";
264	    if (only === "superseded") return "superseded";
265	    if (only === "restatement") return "restatement";
266	    if (only === "echo") return "echo";
267	    return "applied";
268	  }
269	  // Mixed outcomes are exactly what design 5's "fields are independent"
270	  // property produces, and the event records that honestly rather than
271	  // rounding to the best or worst field.
272	  return "partial";
273	}
274	
275	/** The object types the endpoint accepts, for the demo's printed output. */
276	export const ACCEPTED_OBJECT_TYPES: readonly ObjectType[] = ["Customer", "Contact"];
277

