53	 * `JSON.stringify` can reorder keys and change spacing, which would make a
54	 * valid signature fail and an attacker's reordering succeed.
55	 *
56	 * @throws {SignatureInvalid}
57	 */
58	export function verifySignature(rawBody: string, signatureHex: string, secret: string): void {
59	  const expected = createHmac("sha256", secret).update(rawBody, "utf8").digest();
60	  let provided: Buffer;
61	  try {
62	    provided = Buffer.from(signatureHex, "hex");
63	  } catch (cause) {
