65	    // crash. Reported as such rather than allowed to propagate as a TypeError.
66	    throw new SignatureInvalid(`signature is not valid hex: ${String(cause)}`);
67	  }
68	  if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) {
69	    throw new SignatureInvalid();
