8	  EventOutcome,
9	  ObjectType,
10	  Origin,
11	  OutboundReason,
12	  OutboundState,
13	} from "../domain/types.js";
14	
15	/** A row of `customer` or `contact`: the current values, and nowhere else. */
16	export interface RecordRow {
17	  readonly objectType: ObjectType;
18	  readonly portalId: string;
19	  /** field -> current canonical value. The single home of a current value. */
20	  values: Record<string, string | null>;
21	  updatedAtMs: number;
22	}
23	
24	/**
25	 * A row of `field_version`: the winning order key for one field, plus what we
26	 * believe Salesforce holds.
27	 *
28	 * A cache, not a second source of truth — every column is derivable from
29	 * `fieldChanges` and `observations`, and rebuilding it is the repair for any
30	 * doubt (design 4).
31	 */
32	export interface FieldVersionRow {
33	  readonly objectType: ObjectType;
34	  readonly portalId: string;
35	  readonly field: string;
36	  /** The order key of the change that is currently winning. */
37	  occurredAtMs: number;
38	  originRank: number;
39	  originEventId: string;
40	  origin: Origin;
41	  actor: string;
42	  /**
43	   * What we believe Salesforce currently holds for this field. Updated by a
44	   * Salesforce observation **and by our own successful send** — a write of
45	   * ours is the most recent thing we know about Salesforce's state (design
46	   * 6.3; Appendix B traces the divergence that omitting it causes).
47	   * `undefined` until either has happened.
48	   */
49	  sfValue?: string | null;
50	  /** When we last learned `sfValue`. Guards against an old event overwriting a newer fact. */
51	  sfObservedAtMs?: number;
52	}
53	
54	/** A row of `field_change`: permanent history. Append-only, never updated. */
55	export interface FieldChangeRow {
56	  readonly seq: number;
57	  readonly objectType: ObjectType;
58	  readonly portalId: string;
59	  readonly field: string;
60	  readonly oldValue: string | null;
61	  readonly newValue: string | null;
62	  readonly occurredAtMs: number;
63	  readonly origin: Origin;
64	  readonly originEventId: string;
65	  readonly actor: string;
66	  /** Only `applied` and `superseded` live here; both are permanent. */
67	  readonly outcome: "applied" | "superseded";
68	  readonly appliedAtMs: number;
69	}
70	
71	/**
72	 * A row of `sync_observation`: an echo or a confirmation. Neither is an edit
73	 * by a person, so neither belongs in the client's history (design 4).
74	 */
75	export interface ObservationRow {
76	  readonly seq: number;
77	  readonly objectType: ObjectType;
78	  readonly portalId: string;
79	  readonly field: string;
80	  readonly observedValue: string | null;
81	  readonly occurredAtMs: number;
82	  readonly origin: Origin;
83	  readonly originEventId: string;
84	  readonly actor: string;
85	  readonly outcome: "echo" | "confirmed" | "restatement";
86	  readonly observedAtMs: number;
87	}
88	
89	/** A row of `inbound_event`: the duplicate key (design 8.1). */
90	export interface InboundEventRow {
91	  readonly eventId: string;
92	  readonly objectType: ObjectType;
93	  readonly sfId: string;
94	  readonly occurredAtMs: number;
95	  /** sha256 of the raw body; a repeat with a different hash is a provider bug. */
96	  readonly payloadHash: string;
97	  outcome: EventOutcome;
98	  readonly receivedAtMs: number;
99	}
100	
101	/**
102	 * A row of `outbound_change`: the durable queue.
103	 *
104	 * Note what is absent: the value to send. The sender reads the current value
105	 * at send time, so a row queued three hours into an outage cannot deliver a
106	 * value we have since superseded (design 6.3).
107	 */
108	export interface OutboundRow {
109	  readonly id: number;
110	  readonly objectType: ObjectType;
111	  readonly portalId: string;
112	  readonly field: string;
113	  readonly reason: OutboundReason;
114	  readonly occurredAtMs: number;
115	  state: OutboundState;
116	  attempts: number;
117	  nextAttemptAtMs: number;
118	  leaseOwner?: string;
119	  leaseUntilMs?: number;
120	  lastError?: string;
121	  readonly createdAtMs: number;
122	  sentAtMs?: number;
123	}
124	
125	/** A row of `record_link`: identity across the two systems, and the per-record lock. */
126	export interface RecordLinkRow {
127	  readonly objectType: ObjectType;
128	  readonly portalId: string;
129	  /** Null until Salesforce assigns one — a portal-created record has no id yet. */
130	  sfId: string | null;
131	  linkedAtMs?: number;
132	}
133	
134	/** A row of `echo_fence`: "we just wrote this value; expect to hear it back" (design 9.3). */
135	export interface EchoFenceRow {
136	  readonly objectType: ObjectType;
137	  readonly portalId: string;
138	  readonly field: string;
139	  readonly valueHash: string;
140	  readonly sentAtMs: number;
141	  readonly expiresAtMs: number;
142	}
143	
144	/** The whole durable state. One JSON document stands in for the database. */
145	export interface StoreState {
146	  records: Record<string, RecordRow>;
147	  fieldVersions: Record<string, FieldVersionRow>;
148	  fieldChanges: FieldChangeRow[];
149	  observations: ObservationRow[];
150	  inboundEvents: Record<string, InboundEventRow>;
151	  outbound: OutboundRow[];
152	  recordLinks: RecordLinkRow[];
153	  echoFences: EchoFenceRow[];
154	  /** objectType -> highest SystemModstamp we are confident we have seen. */
155	  watermarks: Record<string, number>;
156	  nextSeq: number;
157	  nextOutboundId: number;
158	}
159	
160	/** An empty database. */
161	export function emptyState(): StoreState {
162	  return {
163	    records: {},
164	    fieldVersions: {},
165	    fieldChanges: [],
166	    observations: [],
167	    inboundEvents: {},
168	    outbound: [],
169	    recordLinks: [],
170	    echoFences: [],
171	    watermarks: {},
172	    nextSeq: 1,
173	    nextOutboundId: 1,
174	  };
175	}
176	
177	/** Composite key for `records` and `recordLinks`. */
178	export function recordKey(objectType: ObjectType, portalId: string): string {
179	  return `${objectType}:${portalId}`;
180	}
181	
182	/** Composite key for `fieldVersions`. */
183	export function fieldKey(
184	  objectType: ObjectType,
185	  portalId: string,
186	  field: string,
187	): string {
188	  return `${objectType}:${portalId}:${field}`;
189	}
