1	/**
2	 * Webhook validation: turning bytes from the internet into something the
3	 * merge can be trusted with, or a clear refusal.
4	 *
5	 * The one judgement encoded here is design 5's 400-versus-500 split, and it
6	 * matters because **a 400 discards the event forever** while a 500 asks
7	 * Salesforce to send it again:
8	 *
9	 * - An unknown *field name* earns a 400. No amount of retrying will make
10	 *   `telephon` a field.
11	 * - A *value* we merely failed to handle does **not** earn a 400. That is our
12	 *   bug, and throwing the event away because of our bug would lose a real
13	 *   edit — so it is a 500 and Salesforce retries it.
14	 *
15	 * Every rejection names exactly what was wrong. An unparseable body, a missing
16	 * `eventId`, an unknown `objectType` and an unknown field are four different
17	 * messages, not one generic "bad request", because the first thing anybody
18	 * debugging a webhook asks is *which* part was wrong.
19	 */
20	
21	import { createHmac, timingSafeEqual } from "node:crypto";
22	
23	import { fieldSpec } from "../domain/fields.js";
24	import { WebhookRejected } from "../domain/types.js";
25	import type { ObjectType } from "../domain/types.js";
26	
27	/** A webhook that has been validated and is safe to merge. */
28	export interface ValidWebhook {
29	  readonly eventId: string;
30	  readonly recordId: string;
31	  readonly objectType: ObjectType;
32	  readonly occurredAtMs: number;
33	  readonly changedBy: string;
34	  readonly changedFields: Readonly<Record<string, string | null>>;
35	}
36	
37	/** Raised when the signature does not verify. Distinct from a 400: retrying cannot help. */
38	export class SignatureInvalid extends Error {
39	  readonly status = 401 as const;
40	  constructor(message = "X-Signature did not verify") {
41	    super(message);
42	    this.name = "SignatureInvalid";
43	  }
44	}
45	
46	const OBJECT_TYPES: readonly string[] = ["Customer", "Contact"];
47	
48	/**
49	 * Verify the HMAC-SHA256 signature over the **raw bytes** of the body
50	 * (assumption A7).
51	 *
52	 * Over the raw bytes, never over re-serialised JSON: `JSON.parse` followed by
53	 * `JSON.stringify` can reorder keys and change spacing, which would make a
54	 * valid signature fail and an attacker's reordering succeed.
55	 *
56	 * @throws {SignatureInvalid}
57	 */
58	export function verifySignature(rawBody: string, signatureHex: string, secret: string): void {
59	  const expected = createHmac("sha256", secret).update(rawBody, "utf8").digest();
60	  let provided: Buffer;
61	  try {
62	    provided = Buffer.from(signatureHex, "hex");
63	  } catch (cause) {
64	    // A signature header that is not even hex is a failed signature, not a
65	    // crash. Reported as such rather than allowed to propagate as a TypeError.
66	    throw new SignatureInvalid(`signature is not valid hex: ${String(cause)}`);
67	  }
68	  if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) {
69	    throw new SignatureInvalid();
70	  }
71	}
72	
73	/** Sign a body the way Salesforce would. Used by the demo and the tests. */
74	export function signBody(rawBody: string, secret: string): string {
75	  return createHmac("sha256", secret).update(rawBody, "utf8").digest("hex");
76	}
77	
78	/**
79	 * Parse and validate a raw webhook body.
80	 *
81	 * @throws {WebhookRejected} with status 400 and a specific `reason` for every
82	 *   way the payload can be wrong in a way time will not fix.
83	 */
84	export function validateWebhook(rawBody: string): ValidWebhook {
85	  let parsed: unknown;
86	  try {
87	    parsed = JSON.parse(rawBody);
88	  } catch (cause) {
89	    throw new WebhookRejected(
90	      `body is not valid JSON: ${cause instanceof Error ? cause.message : String(cause)}`,
91	      400,
92	      "malformed-json",
93	    );
94	  }
95	  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
96	    throw new WebhookRejected("body must be a JSON object", 400, "not-an-object");
97	  }
98	  const body = parsed as Record<string, unknown>;
99	
100	  const eventId = body["eventId"];
101	  if (typeof eventId !== "string" || eventId.length === 0) {
102	    throw new WebhookRejected("eventId is required", 400, "missing-eventId");
103	  }
104	  const recordId = body["recordId"];
105	  if (typeof recordId !== "string" || recordId.length === 0) {
106	    throw new WebhookRejected("recordId is required", 400, "missing-recordId");
107	  }
108	  const objectType = body["objectType"];
109	  if (typeof objectType !== "string" || !OBJECT_TYPES.includes(objectType)) {
110	    throw new WebhookRejected(
111	      `objectType must be one of ${OBJECT_TYPES.join(", ")}, got ${JSON.stringify(objectType)}`,
112	      400,
113	      "unknown-objectType",
114	    );
115	  }
116	  const changedBy = body["changedBy"];
117	  if (typeof changedBy !== "string" || changedBy.length === 0) {
118	    throw new WebhookRejected("changedBy is required", 400, "missing-changedBy");
119	  }
120	
121	  const occurredAtMs = parseOccurredAt(body["occurredAt"]);
122	
123	  const changedFieldsRaw = body["changedFields"];
124	  if (
125	    typeof changedFieldsRaw !== "object" ||
126	    changedFieldsRaw === null ||
127	    Array.isArray(changedFieldsRaw)
128	  ) {
129	    throw new WebhookRejected(
130	      "changedFields must be an object",
131	      400,
132	      "bad-changedFields",
133	    );
134	  }
135	  const entries = Object.entries(changedFieldsRaw as Record<string, unknown>);
136	  if (entries.length === 0) {
137	    // An event that names no field tells us nothing and cannot be applied.
138	    throw new WebhookRejected(
139	      "changedFields must name at least one field",
140	      400,
141	      "empty-changedFields",
142	    );
143	  }
144	
145	  const changedFields: Record<string, string | null> = {};
146	  for (const [field, value] of entries) {
147	    if (!fieldSpec(objectType as ObjectType, field)) {
148	      // An unknown field name can never become valid, so this is a 400 and the
149	      // event is discarded. The message names the field and the object type,
150	      // because that is what the person reading the alert needs.
151	      throw new WebhookRejected(
152	        `${objectType} has no field ${JSON.stringify(field)}`,
153	        400,
154	        "unknown-field",
155	      );
156	    }
157	    if (value !== null && typeof value !== "string") {
158	      throw new WebhookRejected(
159	        `field ${field} must be a string or null, got ${typeof value}`,
160	        400,
161	        "bad-field-type",
162	      );
163	    }
164	    changedFields[field] = value;
165	  }
166	
167	  return {
168	    eventId,
169	    recordId,
170	    objectType: objectType as ObjectType,
171	    occurredAtMs,
172	    changedBy,
173	    changedFields,
174	  };
175	}
176	
177	/**
178	 * `occurredAt` must be a parseable instant (assumption A11: UTC, millisecond
179	 * resolution). Accepts an ISO string or an epoch-millisecond number, because
180	 * the demo uses numbers and a real Salesforce sends ISO.
181	 */
182	function parseOccurredAt(value: unknown): number {
183	  if (typeof value === "number" && Number.isFinite(value)) return value;
184	  if (typeof value === "string") {
185	    const ms = Date.parse(value);
186	    if (!Number.isNaN(ms)) return ms;
187	  }
188	  throw new WebhookRejected(
189	    `occurredAt must be an ISO-8601 instant or epoch ms, got ${JSON.stringify(value)}`,
190	    400,
191	    "bad-occurredAt",
192	  );
193	}
