36	  readonly fresh?: boolean;
37	  /**
38	   * How long a clean run must last before the governor steps its rate back up
39	   * (design 6.4 uses 30 s). Most scenarios want this short so they do not
40	   * wait; the rate-cap scenario wants it long, because a fast recovery would
41	   * step the rate back to the ceiling before the scenario can observe that a
