137	  history(objectType: PortalSave["objectType"], portalId: string) {
138	    return this.store.read((tx) => tx.historyFor(objectType, portalId).map((r) => ({ ...r })));
139	  }
140	
141	  /** Every outbound row, for printed output. */
142	  outbound() {
143	    return this.store.read((tx) => tx.outboundRows().map((r) => ({ ...r })));
