1	/**
2	 * A self-contained world for one scenario: a fresh store, a fresh fake
3	 * Salesforce, and the glue that carries a webhook from one to the other.
4	 *
5	 * Each scenario gets its own directory under `.demo-state/`, so scenarios
6	 * cannot contaminate each other and any one of them can be re-run alone while
7	 * debugging.
8	 */
9	
10	import { rmSync } from "node:fs";
11	import { join } from "node:path";
12	
13	import { receiveWebhook } from "../inbound/endpoint.js";
14	import type { WebhookResponse } from "../inbound/endpoint.js";
15	import { signBody, verifySignature } from "../inbound/validate.js";
16	import { savePortalEdit } from "../portal/save.js";
17	import type { PortalSave, PortalSaveResult } from "../portal/save.js";
18	import { RateGovernor } from "../outbound/governor.js";
19	import type { GovernorClock } from "../outbound/governor.js";
20	import { SyncWorker } from "../outbound/worker.js";
21	import { FakeSalesforce, defaultFakePath } from "../salesforce/fake.js";
22	import type { EmittedWebhook } from "../salesforce/fake.js";
23	import { DurableStore, defaultStatePath } from "../store/store.js";
24	
25	/** The shared secret Salesforce signs with (assumption A7). */
26	export const WEBHOOK_SECRET = "demo-shared-secret";
27	
28	export interface WorldOptions {
29	  /** Scenario name; also the state directory. */
30	  readonly name: string;
31	  /** Requests per second the governor allows. The demo uses a low number. */
32	  readonly ceilingPerSecond?: number;
33	  /** Lease duration, shortened so a reclaim is visible. */
34	  readonly leaseMs?: number;
35	  /** Start from empty state. False when a scenario resumes after a restart. */
36	  readonly fresh?: boolean;
37	  /**
38	   * How long a clean run must last before the governor steps its rate back up
39	   * (design 6.4 uses 30 s). Most scenarios want this short so they do not
40	   * wait; the rate-cap scenario wants it long, because a fast recovery would
41	   * step the rate back to the ceiling before the scenario can observe that a
42	   * 429 halved it.
43	   */
44	  readonly recoveryStepMs?: number;
45	}
46	
47	/** Everything a scenario needs. */
48	export class World {
49	  readonly store: DurableStore;
50	  readonly salesforce: FakeSalesforce;
51	  readonly governor: RateGovernor;
52	  readonly worker: SyncWorker;
53	  readonly dir: string;
54	
55	  private constructor(options: WorldOptions, dir: string) {
56	    this.dir = dir;
57	    this.store = DurableStore.open(join(dir, "store.json"));
58	    this.salesforce = FakeSalesforce.open(defaultFakePath(dir));
59	    const clock: GovernorClock = {
60	      nowMs: () => Date.now(),
61	      sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
62	    };
63	    this.governor = new RateGovernor({
64	      ceilingPerSecond: options.ceilingPerSecond ?? 1000,
65	      floorPerSecond: 1,
66	      increasePerStep: 5,
67	      recoveryStepMs: options.recoveryStepMs ?? 200,
68	      clock,
69	    });
70	    this.worker = new SyncWorker(
71	      this.store,
72	      this.salesforce,
73	      this.governor,
74	      `demo-${process.pid}`,
75	      () => Date.now(),
76	      options.leaseMs ?? 30_000,
77	    );
78	  }
79	
80	  /** Build a world, wiping its directory first unless resuming. */
81	  static create(options: WorldOptions): World {
82	    const dir = join(".demo-state", options.name);
83	    if (options.fresh !== false) {
84	      try {
85	        rmSync(dir, { recursive: true, force: true });
86	      } catch (cause) {
87	        // Reported rather than ignored: a scenario starting from stale state
88	        // would produce output that cannot be trusted.
89	        throw new Error(`cannot reset demo state at ${dir}: ${String(cause)}`);
90	      }
91	    }
92	    return new World(options, dir);
93	  }
94	
95	  /** The store path, for a child process to open the same state. */
96	  get storePath(): string {
97	    return defaultStatePath(this.dir);
98	  }
99	
100	  /**
101	   * Deliver one webhook to our endpoint, exactly as Salesforce would: serialise
102	   * it, sign the raw bytes, verify the signature, then hand the raw body to
103	   * the handler.
104	   *
105	   * The signature is verified here rather than skipped, so the demo exercises
106	   * design 5's step 2 even though it is not one of the four rules on show.
107	   */
108	  deliver(event: EmittedWebhook): WebhookResponse {
109	    const rawBody = JSON.stringify({
110	      eventId: event.eventId,
111	      recordId: event.recordId,
112	      objectType: event.objectType,
113	      occurredAt: new Date(event.occurredAtMs).toISOString(),
114	      changedBy: event.changedBy,
115	      changedFields: event.changedFields,
116	    });
117	    verifySignature(rawBody, signBody(rawBody, WEBHOOK_SECRET), WEBHOOK_SECRET);
118	    return receiveWebhook(this.store, rawBody);
119	  }
120	
121	  /** Deliver a hand-built raw body, for the validation checks. */
122	  deliverRaw(rawBody: string): WebhookResponse {
123	    return receiveWebhook(this.store, rawBody);
124	  }
125	
126	  /** A finance or customer-success user saves the portal form. */
127	  save(save: PortalSave): PortalSaveResult {
128	    return savePortalEdit(this.store, save);
129	  }
130	
131	  /** The current values the portal would show. */
132	  portalValues(objectType: PortalSave["objectType"], portalId: string) {
133	    return this.store.read((tx) => ({ ...(tx.getRecord(objectType, portalId)?.values ?? {}) }));
134	  }
135	
136	  /** Permanent history for one record, oldest first. */
137	  history(objectType: PortalSave["objectType"], portalId: string) {
138	    return this.store.read((tx) => tx.historyFor(objectType, portalId).map((r) => ({ ...r })));
139	  }
140	
141	  /** Every outbound row, for printed output. */
142	  outbound() {
143	    return this.store.read((tx) => tx.outboundRows().map((r) => ({ ...r })));
144	  }
145	}
