1	/**
2	 * The exercise's own acceptance scenario (design 7.4, Appendix A).
3	 *
4	 * Sales creates a customer, finance corrects the billing city in the portal,
5	 * sales then changes the phone in Salesforce, and the portal must end with the
6	 * new phone **and** the finance city — with the history of both.
7	 *
8	 * This is the scenario that forces field-level merge (ADR 0002): the two edits
9	 * are concurrent with each other, so any record-level comparison would discard
10	 * one of them, being unable to see that they touched different fields.
11	 */
12	
13	import { check, detail, heading, kv, step, table, why } from "../report.js";
14	import { World } from "../world.js";
15	
16	export async function phoneAndCity(): Promise<void> {
17	  heading(1, "Both sides change the same record, different fields", "7.4 / Appendix A");
18	  const w = World.create({ name: "phone-and-city", ceilingPerSecond: 50 });
19	
20	  // --- sales creates the contact in Salesforce --------------------------------
21	  step("A sales user creates the contact in Salesforce (11:00:00.000).");
22	  const t0 = Date.parse("2026-11-02T11:00:00.000Z");
23	  const { sfId } = w.salesforce.applyExternalEdit({
24	    objectType: "Contact",
25	    changedFields: {
26	      full_name: "Asha Mehta",
27	      phone: "+919876500001",
28	      email: "ASHA@Client.example",
29	      city: "Gurugram",
30	      owner: "sales.user@client.example",
31	    },
32	    actor: "sales.user@client.example",
33	    atMs: t0,
34	  });
35	  for (const event of w.salesforce.drainWebhooks()) {
36	    const res = w.deliver(event);
37	    kv("webhook -> endpoint", `${res.status} ${res.body.status}`);
38	  }
39	  const portalId = w.store.read((tx) => tx.findLinkBySfId("Contact", sfId)?.portalId ?? "");
40	  kv("Salesforce id", sfId);
41	  kv("portal id", portalId.slice(0, 8) + "...");
42	  detail('email was canonicalised: "ASHA@Client.example" -> ' +
43	    JSON.stringify(w.portalValues("Contact", portalId)["email"]));
44	
45	  // --- finance corrects the city in the portal -------------------------------
46	  step("A finance user corrects the billing city in the portal.");
47	  const save = w.save({
48	    objectType: "Contact",
49	    portalId,
50	    actor: "finance.user@client.example",
51	    changedFields: { city: "Noida" },
52	  });
53	  kv("city now", w.portalValues("Contact", portalId)["city"]);
54	  kv("outbound rows queued", w.outbound().filter((r) => r.state === "pending").length);
55	  why(
56	    "the queue row and the value change are the same commit, so there is no " +
57	      "state in which the portal shows Noida and we have forgotten to tell " +
58	      "Salesforce (design 6.1).",
59	  );
60	
61	  // --- the worker sends it ---------------------------------------------------
62	  step("The sync worker sends it to Salesforce.");
63	  const sent = await w.worker.drain();
64	  kv("calls made", sent.callsMade);
65	  kv("Salesforce city", w.salesforce.recordValues(sfId)?.["city"]);
66	  check(sent.callsMade === 1, "one call carried the city — the only real news");
67	
68	  // --- Salesforce echoes our own write ---------------------------------------
69	  step("Salesforce tells us about our own write (the echo).");
70	  let echoOutbound = 0;
71	  for (const event of w.salesforce.drainWebhooks()) {
72	    const res = w.deliver(event);
73	    kv(`echo ${event.eventId} (${event.changedBy.split("@")[0]})`, `${res.status} ${res.body.status}`);
74	    echoOutbound += w.outbound().filter((r) => r.state === "pending").length;
75	  }
76	  check(echoOutbound === 0, "the echo created no outbound work — the loop is dead");
77	
78	  // --- sales changes the phone in Salesforce ---------------------------------
79	  step("A sales user changes the phone in Salesforce (11:05:00.000).");
80	  const t3 = Date.parse("2026-11-02T11:05:00.000Z");
81	  w.salesforce.applyExternalEdit({
82	    objectType: "Contact",
83	    sfId,
84	    changedFields: { phone: "+919876500002" },
85	    actor: "sales.user@client.example",
86	    atMs: t3,
87	  });
88	  for (const event of w.salesforce.drainWebhooks()) {
89	    const res = w.deliver(event);
90	    kv(`webhook ${event.eventId}`, `${res.status} ${res.body.status}`);
91	  }
92	
93	  // --- the result ------------------------------------------------------------
94	  step("The result.");
95	  const values = w.portalValues("Contact", portalId);
96	  kv("portal phone", values["phone"]);
97	  kv("portal city", values["city"]);
98	  check(values["phone"] === "+919876500002", "the portal has the new phone");
99	  check(values["city"] === "Noida", "the portal still has the finance city");
100	
101	  step("The history the client asked for.");
102	  table(
103	    ["field", "old", "new", "actor", "origin", "outcome"],
104	    w.history("Contact", portalId).map((h) => [
105	      h.field,
106	      h.oldValue ?? "-",
107	      h.newValue ?? "-",
108	      (h.actor.split("@")[0] ?? h.actor),
109	      h.origin,
110	      h.outcome,
111	    ]),
112	  );
113	  const phoneChange = w.history("Contact", portalId).find(
114	    (h) => h.field === "phone" && h.newValue === "+919876500002",
115	  );
116	  const cityChange = w.history("Contact", portalId).find(
117	    (h) => h.field === "city" && h.newValue === "Noida",
118	  );
119	  check(
120	    phoneChange?.actor === "sales.user@client.example",
121	    "who changed the phone is on record",
122	  );
123	  check(
124	    cityChange?.actor === "finance.user@client.example",
125	    "who changed the city is on record",
126	  );
127	  check(
128	    cityChange?.oldValue === "Gurugram",
129	    "the value the city displaced is still on record",
130	  );
131	  why(
132	    "the field, not the record, is the unit of sync, so the two edits never " +
133	      "competed. A record-level last-writer-wins would have had to discard one " +
134	      "of them (ADR 0002).",
135	  );
136	}
