1	/**
2	 * The rate cap, and slowing down without losing work (design 6.4).
3	 *
4	 * The design runs at 70 of the 100 requests per second Salesforce allows. The
5	 * exercise permits a lower cap in a demo so the wait is visible, and that is
6	 * what this scenario does — but **the code enforces whatever cap it is
7	 * given**, which is the property on show. The cap counts every request
8	 * including retries, because the exercise is explicit that it does.
9	 *
10	 * The second half is the slow-down signal. Nothing is dropped: the governor
11	 * halves the rate it is willing to spend, and the queue rows go back to
12	 * `pending` with their attempt **restored**, because being throttled was not
13	 * the row's fault.
14	 */
15	
16	import { check, detail, heading, kv, step, why } from "../report.js";
17	import { World } from "../world.js";
18	
19	const CEILING = 4;
20	const RECORDS = 12;
21	
22	export async function rateCap(): Promise<void> {
23	  heading(5, "The rate cap is enforced, and a slow-down keeps the work", "6.4");
24	  // A long recovery step, so the halving a 429 causes is still visible when
25	  // the scenario reads the rate. With a fast recovery the clean responses that
26	  // follow would step it back to the ceiling first, and the demo would be
27	  // measuring the recovery rather than the decrease.
28	  const w = World.create({
29	    name: "rate-cap",
30	    ceilingPerSecond: CEILING,
31	    recoveryStepMs: 60_000,
32	  });
33	
34	  step(`Queue ${RECORDS} separate records, with the governor set to ${CEILING} req/s.`);
35	  detail("Separate records on purpose: coalescing would otherwise collapse them");
36	  detail("into one call, which is the right behaviour but not what is being shown.");
37	  for (let i = 0; i < RECORDS; i += 1) {
38	    w.save({
39	      objectType: "Contact",
40	      actor: "finance.user@client.example",
41	      changedFields: { full_name: `Person ${i}`, city: "Pune" },
42	    });
43	  }
44	  kv("pending outbound rows", w.worker.pendingCount());
45	
46	  step("Drain, and time it.");
47	  const started = Date.now();
48	  await w.worker.drain();
49	  const elapsedMs = Date.now() - started;
50	  const lowerBoundMs = ((RECORDS - CEILING) / CEILING) * 1000;
51	  kv("calls made", w.governor.grantedCount);
52	  kv("elapsed", `${elapsedMs} ms`);
53	  kv("floor implied by the cap", `${Math.round(lowerBoundMs)} ms`);
54	  kv("effective rate", `${(w.governor.grantedCount / (elapsedMs / 1000)).toFixed(1)} req/s`);
55	  check(w.governor.grantedCount === RECORDS, `all ${RECORDS} records were sent`);
56	  check(
57	    elapsedMs >= lowerBoundMs * 0.8,
58	    `the drain took at least the time the ${CEILING} req/s cap allows`,
59	  );
60	  check(w.worker.pendingCount() === 0, "nothing was left behind");
61	  why(
62	    "the bucket starts with one second's worth of tokens, so the first " +
63	      `${CEILING} calls go immediately and the remaining ${RECORDS - CEILING} are ` +
64	      `paced at ${CEILING} per second. Raising the cap shortens this; the code ` +
65	      "does not care what the number is.",
66	  );
67	
68	  // --- the slow-down signal -------------------------------------------------
69	  step("Salesforce says slow down (429 with Retry-After) on the next 3 calls.");
70	  const rateBefore = w.governor.currentRate;
71	  w.salesforce.throttleNext(3, 120);
72	  for (let i = 0; i < 3; i += 1) {
73	    w.save({
74	      objectType: "Contact",
75	      actor: "finance.user@client.example",
76	      changedFields: { city: `City ${i}` },
77	    });
78	  }
79	  const queued = w.worker.pendingCount();
80	  kv("pending outbound rows", queued);
81	  kv("governor rate before", `${rateBefore} req/s`);
82	
83	  const firstPass = await w.worker.drain();
84	  kv("rows that hit a 429", firstPass.throttled);
85	  kv("governor rate after", `${w.governor.currentRate} req/s`);
86	  check(firstPass.throttled >= 3, "every throttled call was recognised as a slow-down");
87	  check(w.governor.currentRate < rateBefore, "the governor halved its rate");
88	
89	  step("Nothing was dropped: the final state is the evidence.");
90	  // Deliberately asserted on the end state rather than on a mid-flight pending
91	  // count. `drain` honours Retry-After and keeps going, so by the time it
92	  // returns the retried work has legitimately completed — "nothing was
93	  // dropped" means every row reached Salesforce, not that a row is still
94	  // sitting in the queue.
95	  await settle(w);
96	  const rows = w.outbound();
