1	/**
2	 * Our own update coming back as a webhook, and not being sent again
3	 * (design 9).
4	 *
5	 * The scenario runs the loop rule three ways, because the design is explicit
6	 * about which layer is the guarantee and which are economy:
7	 *
8	 * - **L1, structural:** outbound work exists only when we believe Salesforce
9	 *   disagrees with us. An echo makes `sf_value` equal the current value, so
10	 *   there is nothing left to disagree about and the loop has no fuel after one
11	 *   hop.
12	 * - **L2, the actor check:** load-bearing, not tidy. The echo carries the time
13	 *   Salesforce stored our write, which is *later* than the edit that write
14	 *   overwrote, so compared as a change it would win and launder our value back
15	 *   over a newer edit from the other side.
16	 * - **canonical form:** the precondition for L1. The scenario makes the fake
17	 *   reformat a phone number the way a real Salesforce does, which is the one
18	 *   way to give a loop fuel if values are compared raw.
19	 */
20	
21	import { check, detail, heading, kv, step, why } from "../report.js";
22	import { World } from "../world.js";
23	
24	export async function loop(): Promise<void> {
25	  heading(4, "Our own update returns as a webhook and is not sent back", "9");
26	  const w = World.create({ name: "loop", ceilingPerSecond: 50 });
27	
28	  step("A finance user sets the city in the portal.");
29	  const { portalId } = w.save({
30	    objectType: "Contact",
31	    actor: "finance.user@client.example",
32	    changedFields: { full_name: "Nikhil Rao", city: "Noida", phone: "+91 98765 00003" },
33	  });
34	  const queued = w.outbound().filter((r) => r.state === "pending").length;
35	  kv("pending outbound rows", queued);
36	  detail(
37	    'phone was canonicalised on the way in: "+91 98765 00003" -> ' +
38	      JSON.stringify(w.portalValues("Contact", portalId)["phone"]),
39	  );
40	  // Asserted before anything else, because every later check in this scenario
41	  // is of the form "and then nothing more was sent". If the first write never
42	  // went out, all of them pass for the wrong reason — which is exactly how a
43	  // real bug in the enqueue condition hid here once.
44	  check(queued > 0, "the portal edit is owed to Salesforce");
45	
46	  step("The worker sends it; Salesforce stores it and emits the echo.");
47	  const first = await w.worker.drain();
48	  kv("calls made", first.callsMade);
49	  check(first.callsMade > 0, "the write actually reached Salesforce");
50	  const echoes = w.salesforce.drainWebhooks();
51	  kv("webhooks Salesforce emitted", echoes.length);
52	  check(echoes.length > 0, "Salesforce emitted the echo we must not act on");
53	
54	  step("We deliver the echo to our own endpoint.");
55	  for (const event of echoes) {
56	    const res = w.deliver(event);
57	    kv(`${event.eventId} by ${event.changedBy.split("@")[0]}`, `${res.status} ${res.body.status}`);
58	  }
59	  const pendingAfterEcho = w.outbound().filter((r) => r.state === "pending").length;
60	  kv("pending outbound rows", pendingAfterEcho);
61	  check(pendingAfterEcho === 0, "the echo created no outbound work");
62	
63	  step("Drain again to prove there is nothing to send.");
64	  const second = await w.worker.drain();
65	  kv("calls made", second.callsMade);
66	  check(second.callsMade === 0, "zero calls — the loop is dead after one hop");
67	  why(
68	    "not because a rule caught it, but because there is nothing left to " +
69	      "disagree about: the send set sf_value to what we wrote, so the one " +
70	      "condition that creates outbound work is false (L1, design 9.1).",
71	  );
72	
73	  // --- L1 survives the actor check being unavailable -------------------------
74	  step("The same echo with an UNRECOGNISABLE actor (assumption A6 false).");
75	  detail("L2 cannot fire, so only L1 and the echo fence are left.");
76	  w.save({
77	    objectType: "Contact",
78	    portalId,
79	    actor: "finance.user@client.example",
80	    changedFields: { city: "Gurugram" },
81	  });
82	  const disguisedSend = await w.worker.drain();
83	  check(disguisedSend.callsMade > 0, "the second write reached Salesforce too");
84	  const raw = w.salesforce.drainWebhooks();
85	  for (const event of raw) {
86	    // Rewrite the actor to a human, defeating L2 on purpose.
87	    const res = w.deliver({ ...event, changedBy: "someone.else@client.example" });
88	    kv(`${event.eventId} by someone.else`, `${res.status} ${res.body.status}`);
89	  }
90	  const afterDisguised = w.outbound().filter((r) => r.state === "pending").length;
91	  kv("pending outbound rows", afterDisguised);
92	  const third = await w.worker.drain();
93	  kv("calls made", third.callsMade);
94	  check(third.callsMade === 0, "still zero calls — L1 holds without the actor check");
95	
96	  // --- canonical form is what makes L1 true ---------------------------------
97	  step("Salesforce reformats a value we sent (why canonical form is load-bearing).");
98	  w.salesforce.reformatOnWrite("+919876500004", "+91 98765 00004");
99	  w.save({
100	    objectType: "Contact",
101	    portalId,
102	    actor: "finance.user@client.example",
103	    changedFields: { phone: "+919876500004" },
104	  });
105	  const reformatSend = await w.worker.drain();
106	  check(reformatSend.callsMade > 0, "the phone write reached Salesforce");
107	  const sfId = w.store.read((tx) => tx.findLinkByPortalId("Contact", portalId)?.sfId ?? "");
108	  const stored = w.salesforce.recordValues(sfId)?.["phone"];
109	  kv("what we sent", w.portalValues("Contact", portalId)["phone"]);
110	  kv("what Salesforce stored", stored);
111	  check(
112	    stored === "+91 98765 00004",
113	    "Salesforce reformatted it, so the echo carries a different spelling",
114	  );
115	  for (const event of w.salesforce.drainWebhooks()) {
116	    const res = w.deliver({ ...event, changedBy: "someone.else@client.example" });
117	    kv(`reformatted echo ${event.eventId}`, `${res.status} ${res.body.status}`);
118	  }
119	  const fourth = await w.worker.drain();
120	  kv("calls made", fourth.callsMade);
121	  check(
122	    fourth.callsMade === 0,
123	    "the two spellings are one canonical value, so the echo is still a no-op",
124	  );
125	  why(
126	    "compared raw, '+91 98765 00004' and '+919876500004' are different values " +
127	      "with a later time, so we would apply the echo, which changes our value, " +
128	      "which creates outbound work, which echoes again. One formatting " +
129	      "difference between the two systems is enough to turn the sync into a " +
130	      "generator of its own traffic (design 7.3).",
131	  );
132	}
