1	/**
2	 * A pending call that is still there after our process restarts, while the
3	 * fake Salesforce is down (design 6.5, 10.2).
4	 *
5	 * The exercise's hard requirement is that pending calls to Salesforce survive
6	 * our own process restarting, so this scenario uses a real child process and
7	 * kills it with `SIGKILL`. There is no orderly shutdown to credit the
8	 * durability to: the row is on disk because it was committed in the same
9	 * transaction as the portal edit that created it, which is what ADR 0001
10	 * bought.
11	 *
12	 * It then shows the second half of a restart — a row the dead sender had
13	 * already claimed is reclaimed when its lease expires, with no manual
14	 * intervention and no reconciliation script.
15	 */
16	
17	import { spawnSync } from "node:child_process";
18	
19	import { check, detail, heading, kv, step, table, why } from "../report.js";
20	import { World } from "../world.js";
21	
22	const SCENARIO = "restart";
23	
24	export async function restart(): Promise<void> {
25	  heading(6, "A pending call survives a restart while Salesforce is down", "6.5 / 10.2");
26	  const w = World.create({ name: SCENARIO, ceilingPerSecond: 50, leaseMs: 800 });
27	
28	  step("Take the Salesforce record API down (the 6-hour outage of design 10).");
29	  w.salesforce.setDown(true);
30	  kv("salesforce reachable", !w.salesforce.isDown);
31	
32	  step("A finance user saves anyway. The portal keeps working throughout.");
33	  const { portalId } = w.save({
34	    objectType: "Contact",
35	    actor: "finance.user@client.example",
36	    changedFields: { full_name: "Priya Nair", city: "Kochi", phone: "+919876500010" },
37	  });
38	  kv("portal city (visible at once)", w.portalValues("Contact", portalId)["city"]);
39	  const queued = w.outbound().filter((r) => r.state === "pending");
40	  kv("pending outbound rows", queued.length);
41	  kv("bytes of queue on disk", JSON.stringify(queued).length);
42	  detail("Nothing is read-only and nothing is refused. The only cost of the");
43	  detail("outage is visibility in Salesforce.");
44	
45	  step("A separate process tries to drain, fails, and is SIGKILLed.");
46	  const first = spawnSync(
47	    process.execPath,
48	    ["dist/demo/restartChild.js", SCENARIO, "attempt-while-down"],
49	    { encoding: "utf8" },
50	  );
51	  process.stdout.write(first.stdout ?? "");
52	  if (first.stderr) process.stderr.write(first.stderr);
53	  kv("child terminated by", first.signal ?? `exit ${first.status}`);
54	  check(first.signal === "SIGKILL", "the child died hard, with no orderly shutdown");
55	
56	  step("Our process reads the state file the dead child left behind.");
57	  const after = World.create({ name: SCENARIO, fresh: false, ceilingPerSecond: 50, leaseMs: 800 });
58	  const survived = after.outbound();
59	  table(
60	    ["id", "field", "reason", "state", "attempts", "lastError"],
61	    survived.map((r) => [
62	      String(r.id),
63	      r.field,
64	      r.reason,
65	      r.state,
66	      String(r.attempts),
67	      (r.lastError ?? "-").slice(0, 28),
68	    ]),
69	  );
70	  check(survived.length > 0, "the pending calls are still there");
71	  check(
72	    survived.every((r) => r.state === "pending"),
73	    "and they are pending, not lost and not failed",
74	  );
75	  check(
76	    survived.every((r) => r.attempts === 0),
77	    "with their attempts restored — an unreachable endpoint is not the row's fault",
78	  );
79	  why(
80	    "ten attempts at a backoff capped at five minutes is under an hour, so if " +
81	      "an unreachable Salesforce counted against the row, every queued call " +
82	      "would have marked itself failed during the second hour of a six-hour " +
83	      "outage. The backlog would have destroyed itself while waiting (design 6.4).",
84	  );
85	
86	  step("Simulate a sender that died mid-call: a row left inflight, lease expired.");
87	  after.store.transaction((tx) => {
88	    const row = tx.outboundRows()[0];
89	    if (!row) throw new Error("expected at least one queued row");
90	    row.state = "inflight";
91	    row.leaseOwner = "sender-that-died";
92	    row.leaseUntilMs = Date.now() - 1; // already expired
93	  });
