1	/**
2	 * A fake Salesforce, written for this demo. Nothing here talks to a network.
3	 *
4	 * It is the second adapter at the {@link SalesforceClient} seam, and it exists
5	 * to make four behaviours of the real thing reproducible:
6	 *
7	 * 1. **It echoes.** Every write — ours or a sales user's — appends a webhook
8	 *    to {@link FakeSalesforce.drainWebhooks}'s outbox, stamped with the fake's
9	 *    own clock and attributed to whoever made it. Our own writes come back
10	 *    attributed to the integration user, which is the echo the loop rule has
11	 *    to survive (design 9.2).
12	 * 2. **It can be unreachable**, which is the 6-hour outage of design 10.
13	 * 3. **It can tell us to slow down**, which is assumption A8's 429.
14	 * 4. **It can refuse a record's data**, which is the row failure of design 6.5.
15	 *
16	 * Its state lives in its own JSON file, so a demo that kills and restarts a
17	 * process finds the fake exactly as it left it — including whether it is down.
18	 * That is what makes the restart scenario real rather than simulated.
19	 */
20	
21	import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
22	import { dirname, join } from "node:path";
23	
24	import { StoreReadError, StoreWriteError } from "../domain/types.js";
25	import type { ObjectType } from "../domain/types.js";
26	import type { ChangedRecord, SalesforceClient } from "./client.js";
27	import {
28	  INTEGRATION_USER,
29	  SalesforceRejected,
30	  SalesforceThrottled,
31	  SalesforceUnreachable,
32	} from "./client.js";
33	
34	/** A webhook the fake has emitted and we have not yet delivered. */
35	export interface EmittedWebhook {
36	  readonly eventId: string;
37	  readonly recordId: string;
38	  readonly objectType: ObjectType;
39	  /** The fake's own clock — a different clock from ours (design 7.6). */
40	  readonly occurredAtMs: number;
41	  readonly changedBy: string;
42	  readonly changedFields: Record<string, string | null>;
43	}
44	
45	interface FakeRecord {
46	  objectType: ObjectType;
47	  values: Record<string, string | null>;
48	  systemModstampMs: number;
49	  lastModifiedBy: string;
50	  /** The external id we upserted on, when the record came from the portal. */
51	  externalId?: string;
52	}
53	
54	interface FakeState {
55	  records: Record<string, FakeRecord>;
56	  outbox: EmittedWebhook[];
57	  nextSfId: number;
58	  nextEventId: number;
59	  /** True while the record API is unreachable (design 10). */
60	  down: boolean;
61	  /** This many of the next calls answer 429 instead of succeeding. */
62	  throttleNextCalls: number;
63	  /** Retry-After the fake reports with a 429, in ms. */
64	  throttleRetryAfterMs: number;
65	  /** Writes touching this field are refused as invalid data. */
66	  rejectField: string | null;
67	  /**
68	   * Values the fake rewrites on write, to reproduce Salesforce reformatting
69	   * what we sent. Used to show why canonical form is load-bearing (design 7.3).
70	   */
71	  reformat: Record<string, string>;
72	}
73	
74	function emptyFakeState(): FakeState {
75	  return {
76	    records: {},
77	    outbox: [],
78	    nextSfId: 1,
79	    nextEventId: 1,
80	    down: false,
81	    throttleNextCalls: 0,
82	    throttleRetryAfterMs: 50,
83	    rejectField: null,
84	    reformat: {},
85	  };
86	}
87	
88	/** Default on-disk location for the fake's state. */
89	export function defaultFakePath(dir = ".demo-state"): string {
90	  return join(dir, "salesforce.json");
91	}
92	
93	/**
94	 * The fake. Construct one per process; it reads and writes its own file, so
95	 * two processes in sequence see one Salesforce.
96	 */
97	export class FakeSalesforce implements SalesforceClient {
98	  private state: FakeState;
99	
100	  private constructor(
101	    private readonly path: string,
102	    state: FakeState,
103	    private readonly nowMs: () => number,
104	  ) {
105	    this.state = state;
106	  }
107	
108	  /**
109	   * Open the fake's state, creating it if absent.
110	   *
111	   * @throws {StoreReadError} if the file exists but cannot be read or parsed.
112	   *   Fatal on purpose: silently starting from an empty Salesforce would make
113	   *   the demo's output a lie.
114	   */
115	  static open(path: string, nowMs: () => number = () => Date.now()): FakeSalesforce {
116	    if (!existsSync(path)) {
117	      const fake = new FakeSalesforce(path, emptyFakeState(), nowMs);
118	      fake.persist();
119	      return fake;
120	    }
121	    let raw: string;
122	    try {
123	      raw = readFileSync(path, "utf8");
124	    } catch (cause) {
125	      throw new StoreReadError(`cannot read fake Salesforce at ${path}`, cause);
126	    }
127	    try {
128	      return new FakeSalesforce(path, JSON.parse(raw) as FakeState, nowMs);
129	    } catch (cause) {
130	      throw new StoreReadError(`fake Salesforce at ${path} is not valid JSON`, cause);
131	    }
132	  }
133	
134	  // ----------------------------------------------------------- test levers
135	
136	  /** Take the record API down (design 10's outage) or bring it back up. */
137	  setDown(down: boolean): void {
138	    this.state.down = down;
139	    this.persist();
140	  }
141	
142	  /** True while the record API is unreachable. */
143	  get isDown(): boolean {
144	    return this.state.down;
145	  }
146	
147	  /** Make the next `calls` writes answer 429 with `Retry-After` (A8). */
148	  throttleNext(calls: number, retryAfterMs = 50): void {
149	    this.state.throttleNextCalls = calls;
150	    this.state.throttleRetryAfterMs = retryAfterMs;
151	    this.persist();
152	  }
153	
154	  /** Make writes touching `field` fail as invalid data (a row failure). */
155	  rejectWritesTo(field: string | null): void {
156	    this.state.rejectField = field;
157	    this.persist();
158	  }
159	
160	  /**
161	   * Make the fake rewrite a value on write, the way a real Salesforce
162	   * reformats a phone number. Used to show that canonical form is what keeps
163	   * the echo a no-op (design 7.3, 9.1).
164	   */
165	  reformatOnWrite(from: string, to: string): void {
166	    this.state.reformat[from] = to;
167	    this.persist();
168	  }
169	
170	  // ------------------------------------------------------ the sales user's side
171	
172	  /**
173	   * A sales user edits a record directly in Salesforce.
174	   *
175	   * `atMs` is the time Salesforce puts on the event. The caller passes it
176	   * explicitly so the demo can produce an out-of-order delivery deliberately
177	   * rather than hoping for one.
178	   */
179	  applyExternalEdit(args: {
180	    objectType: ObjectType;
181	    sfId?: string;
182	    changedFields: Record<string, string | null>;
183	    actor: string;
184	    atMs: number;
185	  }): { sfId: string; event: EmittedWebhook } {
186	    const sfId = args.sfId ?? this.mintSfId(args.objectType);
187	    const record = this.state.records[sfId] ?? {
188	      objectType: args.objectType,
189	      values: {},
190	      systemModstampMs: args.atMs,
191	      lastModifiedBy: args.actor,
192	    };
193	    for (const [field, value] of Object.entries(args.changedFields)) {
194	      record.values[field] = value;
195	    }
196	    record.systemModstampMs = args.atMs;
197	    record.lastModifiedBy = args.actor;
198	    this.state.records[sfId] = record;
199	    const event = this.emit(sfId, args.objectType, args.changedFields, args.actor, args.atMs);
200	    this.persist();
201	    return { sfId, event };
202	  }
203	
204	  /**
205	   * Take every webhook the fake has emitted and not yet handed over.
206	   *
207	   * The demo delivers these to our endpoint, in whatever order it chooses —
208	   * which is how the out-of-order scenario is produced.
209	   */
210	  drainWebhooks(): readonly EmittedWebhook[] {
211	    const out = this.state.outbox;
212	    this.state.outbox = [];
213	    this.persist();
214	    return out;
215	  }
216	
217	  /** What Salesforce currently holds, for the demo's final comparison. */
218	  recordValues(sfId: string): Readonly<Record<string, string | null>> | undefined {
219	    return this.state.records[sfId]?.values;
220	  }
221	
222	  // -------------------------------------------------- the SalesforceClient seam
223	
224	  /** @inheritDoc */
225	  async update(
226	    objectType: ObjectType,
227	    sfId: string,
228	    values: Readonly<Record<string, string | null>>,
229	  ): Promise<void> {
230	    this.guardCall(values);
231	    const record = this.state.records[sfId];
232	    if (!record) {
233	      // A 404 from the real thing. Deletes are out of scope (A15), so this is
234	      // unexpected by definition and is a row failure, not a retry.
235	      throw new SalesforceRejected(`no ${objectType} record ${sfId}`);
236	    }
237	    this.writeValues(record, values);
238	    record.systemModstampMs = this.nowMs();
239	    record.lastModifiedBy = INTEGRATION_USER;
240	    // Salesforce tells us about our own write, which is the echo (design 9.2).
241	    this.emit(sfId, objectType, record.values, INTEGRATION_USER, record.systemModstampMs, values);
242	    this.persist();
243	  }
244	
245	  /** @inheritDoc */
246	  async upsertByExternalId(
247	    objectType: ObjectType,
248	    portalId: string,
249	    values: Readonly<Record<string, string | null>>,
250	  ): Promise<{ sfId: string; created: boolean }> {
251	    this.guardCall(values);
252	    const existing = Object.entries(this.state.records).find(
253	      ([, r]) => r.externalId === portalId && r.objectType === objectType,
254	    );
255	    // Idempotent by construction: keyed on OUR identifier, so a repeat updates
256	    // the record it created rather than making a second one (A5).
257	    const sfId = existing?.[0] ?? this.mintSfId(objectType);
258	    const record =
259	      existing?.[1] ??
260	      ({
261	        objectType,
262	        values: {},
263	        systemModstampMs: this.nowMs(),
264	        lastModifiedBy: INTEGRATION_USER,
265	        externalId: portalId,
266	      } satisfies FakeRecord);
267	    this.writeValues(record, values);
268	    record.systemModstampMs = this.nowMs();
269	    record.lastModifiedBy = INTEGRATION_USER;
270	    this.state.records[sfId] = record;
271	    this.emit(sfId, objectType, record.values, INTEGRATION_USER, record.systemModstampMs, values);
272	    this.persist();
273	    return { sfId, created: existing === undefined };
274	  }
275	
276	  /** @inheritDoc */
277	  async queryChangedSince(
278	    objectType: ObjectType,
279	    sinceMs: number,
280	    pageSize: number,
281	  ): Promise<readonly ChangedRecord[]> {
282	    // A read, but it still fails when the API is unreachable.
283	    if (this.state.down) throw new SalesforceUnreachable();
284	    return Object.entries(this.state.records)
285	      .filter(([, r]) => r.objectType === objectType && r.systemModstampMs > sinceMs)
286	      .sort((a, b) => a[1].systemModstampMs - b[1].systemModstampMs)
287	      .slice(0, pageSize)
288	      .map(([sfId, r]) => ({
289	        sfId,
290	        objectType: r.objectType,
291	        // Inherently full-record, and stamped with the RECORD's modification
292	        // time, not each field's — which is why the restatement rule has to be
293	        // unconditional (design 10.3).
294	        values: { ...r.values },
295	        systemModstampMs: r.systemModstampMs,
296	        lastModifiedBy: r.lastModifiedBy,
297	      }));
298	  }
299	
300	  // -------------------------------------------------------------- internals
301	
302	  /** The failure levers, checked in the order the real API would hit them. */
303	  private guardCall(values: Readonly<Record<string, string | null>>): void {
304	    if (this.state.down) throw new SalesforceUnreachable();
305	    if (this.state.throttleNextCalls > 0) {
306	      this.state.throttleNextCalls -= 1;
307	      this.persist();
308	      throw new SalesforceThrottled(this.state.throttleRetryAfterMs);
309	    }
310	    const rejected = this.state.rejectField;
311	    if (rejected !== null && Object.prototype.hasOwnProperty.call(values, rejected)) {
312	      throw new SalesforceRejected(
313	        `INVALID_FIELD: ${rejected} is not acceptable to Salesforce`,
314	      );
315	    }
316	  }
317	
318	  /** Apply values, applying any configured reformatting. */
319	  private writeValues(
320	    record: FakeRecord,
321	    values: Readonly<Record<string, string | null>>,
322	  ): void {
323	    for (const [field, value] of Object.entries(values)) {
324	      const rewritten = value !== null ? this.state.reformat[value] : undefined;
325	      record.values[field] = rewritten ?? value;
326	    }
327	  }
328	
329	  private mintSfId(objectType: ObjectType): string {
330	    const prefix = objectType === "Contact" ? "003" : "001";
331	    return `${prefix}1A0000${String(this.state.nextSfId++).padStart(4, "0")}`;
332	  }
333	
334	  /**
335	   * Append a webhook to the outbox.
336	   *
337	   * `changedOnly` lets a write report just the fields it touched, which is
338	   * assumption A3's changed-fields-only shape. Passing the whole record
339	   * instead produces the full-record shape of design 8.4, and the demo uses
340	   * both.
341	   */
342	  private emit(
343	    sfId: string,
344	    objectType: ObjectType,
345	    allValues: Record<string, string | null>,
346	    changedBy: string,
347	    atMs: number,
348	    changedOnly?: Readonly<Record<string, string | null>>,
349	  ): EmittedWebhook {
350	    const source = changedOnly ?? allValues;
351	    const changedFields: Record<string, string | null> = {};
352	    for (const field of Object.keys(source)) {
353	      changedFields[field] = allValues[field] ?? null;
354	    }
355	    const event: EmittedWebhook = {
356	      eventId: `evt_${this.state.nextEventId++}`,
357	      recordId: sfId,
358	      objectType,
359	      occurredAtMs: atMs,
360	      changedBy,
361	      changedFields,
362	    };
363	    this.state.outbox.push(event);
364	    return event;
365	  }
366	
367	  /**
368	   * Write the fake's state atomically.
369	   *
370	   * @throws {StoreWriteError} with the cause attached. Surfaced rather than
371	   *   swallowed: if the fake's state did not persist, a later step of the demo
372	   *   would be reasoning about a Salesforce that does not exist.
373	   */
374	  private persist(): void {
375	    const tmp = `${this.path}.tmp`;
376	    try {
377	      mkdirSync(dirname(this.path), { recursive: true });
378	      writeFileSync(tmp, JSON.stringify(this.state, null, 2), "utf8");
379	      renameSync(tmp, this.path);
380	    } catch (cause) {
381	      throw new StoreWriteError(`cannot write fake Salesforce at ${this.path}`, cause);
382	    }
383	  }
384	}
