1	/**
2	 * Printing helpers for the demo.
3	 *
4	 * The demo's output is the deliverable the exercise asks to see run, so it is
5	 * written to be read by a person who has the design document open beside it:
6	 * every scenario names the rule it is exercising and the design section that
7	 * rule lives in, then shows the evidence, then states the check that passed.
8	 */
9	
10	const WIDTH = 78;
11	
12	/** A scenario heading, with the design section it exercises. */
13	export function heading(n: number, title: string, section: string): void {
14	  console.log("");
15	  console.log("=".repeat(WIDTH));
16	  console.log(`  ${n}. ${title}`);
17	  console.log(`     design ${section}`);
18	  console.log("=".repeat(WIDTH));
19	}
20	
21	/** A step within a scenario. */
22	export function step(text: string): void {
23	  console.log(`\n  ${text}`);
24	}
25	
26	/** An indented detail line. */
27	export function detail(text: string): void {
28	  console.log(`      ${text}`);
29	}
30	
31	/** A labelled value. */
32	export function kv(label: string, value: unknown): void {
33	  console.log(`      ${label.padEnd(34)} ${String(value)}`);
34	}
35	
36	/**
37	 * A check that must hold.
38	 *
39	 * Throws on failure rather than printing and continuing: a demo that prints
40	 * "FAIL" and carries on to a cheerful summary is worse than one that stops,
41	 * because the summary is what a reader remembers.
42	 */
43	export function check(passed: boolean, description: string): void {
44	  if (!passed) {
45	    console.log(`      [FAIL] ${description}`);
46	    throw new Error(`demo check failed: ${description}`);
47	  }
48	  console.log(`      [ok]   ${description}`);
49	}
50	
51	/** A short explanation of why the rule is shaped the way it is. */
52	export function why(text: string): void {
53	  console.log("");
54	  for (const line of wrap(`why: ${text}`, WIDTH - 6)) {
55	    console.log(`      ${line}`);
56	  }
57	}
58	
59	/** A table of rows, for history and queue listings. */
60	export function table(headers: readonly string[], rows: readonly (readonly string[])[]): void {
61	  const widths = headers.map((h, i) =>
62	    Math.max(h.length, ...rows.map((r) => (r[i] ?? "").length)),
63	  );
64	  const line = (cells: readonly string[]) =>
65	    `      ${cells.map((c, i) => (c ?? "").padEnd(widths[i] ?? 0)).join("  ")}`;
66	  console.log(line(headers));
67	  console.log(`      ${widths.map((w) => "-".repeat(w)).join("  ")}`);
68	  for (const row of rows) console.log(line(row));
69	}
70	
71	/** Wrap text to a width, for the `why` notes. */
72	function wrap(text: string, width: number): string[] {
73	  const words = text.split(/\s+/);
74	  const lines: string[] = [];
75	  let current = "";
76	  for (const word of words) {
